<script setup lang="ts">
import { Play } from 'lucide-vue-next'
import { computed } from 'vue'
import RadialProgress from 'vue3-radial-progress'
import { useRoomMediaLightbox } from '../composables/useRoomMediaLightbox'
import { useImkitStore } from '../stores/imkit'
import { MessageStatus, VideoMessage } from './../classes/message'
import ContentLightboxDialog from './ui/ContentLightboxDialog.vue'
import MediaImg from './ui/MediaImg.vue'

const props = defineProps<{ message: VideoMessage }>()

// Calculate responsive dimensions for stable layout
const containerSize = computed(() => {
  const { width, height } = props.message.video
  const maxSize = 400
  // `2rem`, matching the `-mx-4` on the container below: that pulls the video
  // 1rem past each edge of the bubble's padding box, so the width it is
  // allowed to reach is the parent's width plus 2rem. This said `1.5rem`
  // until 2026-08-17 — 0.5rem short — which capped the video 8px inside the
  // bubble and left a strip of `bg-message` down its right edge. Measured on
  // both orientations: a 1920x1050 video rendered 392px inside a 400px
  // bubble, a 1080x1920 one 217px inside 225px, gap 0 on the other three
  // sides in both cases. If the container's horizontal margin ever changes,
  // this constant has to change with it.
  const maxWidth = 'calc(100% + 2rem)'

  // Fallback to default size if dimensions are missing or invalid
  if (!width || !height || width <= 0 || height <= 0) {
    return { width: '200px', maxWidth, aspectRatio: '16 / 9' }
  }

  // Scale down to fit within maxSize while maintaining aspect ratio
  if (width >= height) {
    const scaledWidth = Math.min(width, maxSize)
    return {
      width: `${scaledWidth}px`,
      maxWidth,
      aspectRatio: `${width} / ${height}`
    }
  } else {
    const scaledHeight = Math.min(height, maxSize)
    const scaledWidth = (scaledHeight * width) / height
    return {
      width: `${scaledWidth}px`,
      maxWidth,
      aspectRatio: `${width} / ${height}`
    }
  }
})

const imkit = useImkitStore()
const uploadProgresses = computed(() => imkit.uploadProgresses)

// Lightbox state
const {
  open: lightboxOpen,
  mediaIndex: lightboxIndex,
  mediaItems: previewMediaItems,
  activeMediaItem,
  selectedMedia,
  mediaCount,
  canNavigatePrevious,
  canNavigateNext,
  openMessageMedia,
  previousMedia,
  nextMedia,
  close: closeLightbox
} = useRoomMediaLightbox(() => props.message)
const selectedVideo = computed(() => {
  return activeMediaItem.value?.kind === 'video'
    ? activeMediaItem.value.video
    : null
})

const handlePlayButtonClick = () => {
  openMessageMedia(
    (item) => item.kind === 'video' && item.video.id === props.message.video.id
  )
}
</script>

<template>
  <!-- `-mx-4 -my-2.5` matches the bubble wrapper's `px-4 py-2.5`
       (MessageCell.vue) exactly, per the precedent documented at
       MixedMessageContent.vue:308 — the video reaches the padding box and
       gets clipped to the bubble's own corners (20px, squared to 6px when
       grouped) by that wrapper's `overflow-hidden`, instead of rounding
       itself (dropped `rounded-lg`) inside a rounded bubble. Was stale
       `-mx-3 -my-2` from before the wrapper moved to `px-4 py-2.5`, leaving a
       4px/2px gap the video didn't reach. -->
  <div
    class="relative -mx-4 -my-2.5 flex cursor-pointer items-center justify-center overflow-hidden"
    :style="containerSize"
    @click="handlePlayButtonClick"
  >
    <MediaImg
      :url="message.video.thumbnailUrl"
      kind="video"
      no-callout
      img-class="h-full w-full border-0 object-cover transition"
    />
    <template
      v-if="
        message.video.thumbnailUrl?.startsWith('data') &&
        message.status !== MessageStatus.Failed
      "
    >
      <!-- `bg-black/50`, not the raw gray-800 fill at 50% this used to be
           (spelled out, because naming the class here would compile it: a
           Tailwind scans comments too, so the dead rule would ship). A fixed
           dark overlay in both colour modes (see the no-`scrim-accent`-token
           note in src/style.css), so it needs no token — `black` isn't a
           themed palette shade, same reasoning CLAUDE.md gives for
           `text-white` needing none.

           ImageMessageContent, MixedMessageContent and ContentLightboxDialog
           now carry the same scrim and deliberately carry no copy of this
           note. Four identical one-line overlays do not need four
           explanations; this is the one. -->
      <div class="absolute inset-0 bg-black/50" />
      <div
        class="pointer-events-none absolute inset-0 flex items-center justify-center"
      >
        <!--
          White, matching Image/MixedMessageContent — NOT the accent tokens
          FileMessageContent uses. This ring sits on the dark scrim over a
          video thumbnail, so it has to read against an arbitrary photo in both
          themes, and white is white in both (the same reason `text-white`
          needs no token). File's ring sits on a message bubble rather than a
          photo, which is why that one takes accent instead.

          Was a hardcoded `#60a5fa` — off-palette, and it would not have
          followed a palette change. RadialProgress writes these onto SVG
          presentation attributes, which no class can reach, so they have to be
          passed as props.
        -->
        <RadialProgress
          :diameter="48"
          :completed-steps="(uploadProgresses[message.video.id] ?? 0) * 100"
          :total-steps="100"
          :start-color="'white'"
          :stop-color="'white'"
          :inner-stroke-color="'rgb(255 255 255 / 0.35)'"
          :stroke-width="4"
          :inner-stroke-width="4"
        >
          <span class="text-xs font-medium text-white">
            {{ Math.round((uploadProgresses[message.video.id] ?? 0) * 100) }}%
          </span>
        </RadialProgress>
      </div>
    </template>
    <template v-else>
      <div
        data-testid="video-play-overlay"
        class="pointer-events-none absolute inset-0 flex items-center justify-center"
      >
        <!-- Solid filled accent circle, same treatment as the audio
             message's play button (AudioMessageContent.vue) instead of a
             thin outline glyph over the scrim, so it reads at a glance over
             any thumbnail. `fill="currentColor"` softens the triangle edge;
             white always reads on `bg-accent` (src/style.css /
             tests/tokenContrast.test.ts). -->
        <div
          class="flex h-12 w-12 items-center justify-center rounded-full bg-accent text-white"
        >
          <Play :size="24" class="ml-0.5" fill="currentColor" />
        </div>
      </div>
      <div
        class="absolute right-2 bottom-2 rounded-full bg-black/30 px-2 py-1 text-xs font-bold text-white"
      >
        {{ Math.floor(message.video.duration / 60) }}:{{
          `${Math.floor(message.video.duration % 60)}`.padStart(2, '0')
        }}
      </div>
    </template>
  </div>

  <ContentLightboxDialog
    :open="lightboxOpen"
    :video="selectedVideo"
    :media-items="previewMediaItems"
    :media-index="lightboxIndex"
    :selected-media="selectedMedia"
    :media-count="mediaCount"
    :can-navigate-previous="canNavigatePrevious"
    :can-navigate-next="canNavigateNext"
    :previous-media="previousMedia"
    :next-media="nextMedia"
    :room-id="message.roomId"
    @update:open="lightboxOpen = $event"
    @update:media-index="lightboxIndex = $event"
    @close="closeLightbox"
  />
</template>

