<script setup lang="ts">
import { computed } from 'vue'
import { TemplateMessage } from './../../classes/message'
import actionHandler from './../../utils/line-action-handler'
const props = defineProps<{ message: TemplateMessage }>()
const isIncoming = computed(() => props.message.isIncoming)
</script>

<template>
  <div class="flex cursor-pointer gap-2 overflow-auto text-base">
    <div
      v-for="(column, index) in message.template.columns"
      :key="index"
      class="w-[250px] cursor-pointer overflow-hidden rounded-lg text-base"
      :class="
        isIncoming
          ? 'bg-message text-content'
          : 'bg-message-own text-message-own-content'
      "
    >
      <img
        v-if="column.thumbnailImageUrl"
        class="object-cover"
        :class="{
          'object-contain': message.template.imageSize === 'contain'
        }"
        :style="{
          'background-color':
            column.imageBackgroundColor ?? 'var(--color-surface-muted)',
          height: `${
            message.template.imageAspectRatio === 'square' ? 250 : 250 / 1.51
          }px`
        }"
        :src="column.thumbnailImageUrl"
        @click="actionHandler(message.roomId, column.defaultAction)"
      />
      <div
        data-testid="template-message-body"
        class="flex flex-col gap-1 px-4 py-2.5"
        @click="actionHandler(message.roomId, column.defaultAction)"
      >
        <div>{{ column.title?.substring(0, 40) }}</div>
        <div
          v-if="column.text"
          class="text-base"
          :class="
            isIncoming ? 'text-content-subtle' : 'text-message-own-content'
          "
        >
          {{
            !column.thumbnailImageUrl && !column.title
              ? column.text.substring(0, 160)
              : column.text.substring(0, 60)
          }}
        </div>
      </div>
      <div
        v-if="(column.actions?.length ?? 0) > 0"
        class="flex flex-col gap-2 border-t py-3"
        :class="
          isIncoming ? 'border-content/8' : 'border-message-own-content/14'
        "
      >
        <div
          v-for="action in column.actions ?? []"
          :key="action.label"
          class="flex items-center justify-center p-0.5 text-base"
          :class="
            isIncoming ? 'text-content-muted' : 'text-message-own-content'
          "
          @click="actionHandler(message.roomId, action)"
        >
          {{ action.label }}
        </div>
      </div>
    </div>
  </div>
</template>

<style scoped></style>
