<script setup lang="ts">
import { Reply } from 'lucide-vue-next'
import { computed, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import RadialProgress from 'vue3-radial-progress'
import IMImage from '../classes/image'
import { useImkitModal as useModal } from '../composables/useImkitModal'
import { useRoomMediaLightbox } from '../composables/useRoomMediaLightbox'
import { getConfig } from '../runtime/config'
import { useImkitStore } from '../stores/imkit'
import { joinFileName } from '../utils/fileName'
import { highlightHtmlText } from '../utils/highlightHtmlText'
import { calculateImageSize } from '../utils/image-size'
import Message, {
  FileMessage,
  MessageStatus,
  MessageType,
  MixedMessage,
  TextMessage
} from './../classes/message'
import AvatarModal from './AvatarModal.vue'
import ContentLightboxDialog from './ui/ContentLightboxDialog.vue'
import MediaImg from './ui/MediaImg.vue'

const props = defineProps<{ message: MixedMessage }>()
const imkit = useImkitStore()
const config = getConfig()

// --- Reply handling (from TextMessageContent) ---
const replyMessage = computed((): Message | undefined => {
  if (!props.message.replyId) return undefined
  return imkit.messageMultiLists
    .get(imkit.selectedRoomId)
    ?.main?.map.get(props.message.replyId)
})
const replyMessageSender = computed(() => {
  const reply = replyMessage.value
  if (!reply) return null
  return imkit.users[reply.senderId]
})

const description = computed((): string => {
  if (!replyMessage.value) return ''
  if (replyMessage.value.type === MessageType.Text) {
    return (replyMessage.value as TextMessage).string
  } else if (replyMessage.value.type === MessageType.Mixed) {
    return (replyMessage.value as MixedMessage).string
  } else if (replyMessage.value.type === MessageType.File) {
    const file = replyMessage.value as FileMessage
    return joinFileName(file.fileName, file.fileExtension)
  } else if (
    replyMessage.value.type === MessageType.Image ||
    replyMessage.value.type === MessageType.Video ||
    replyMessage.value.type === MessageType.Sticker
  ) {
    const { t } = useI18n()
    const messageTypeName = {
      [MessageType.Image]: t('image'),
      [MessageType.Video]: t('video'),
      [MessageType.Sticker]: t('sticker')
    }
    return messageTypeName[replyMessage.value.type]
  }
  return ''
})

// True when this message points at a replyId but the target isn't in the
// loaded message map — either it was deleted, or it hasn't been fetched.
// Rendered as a greyed, non-clickable line rather than silently omitted.
const replyUnavailable = computed(
  () => !!props.message.replyId && !replyMessage.value
)

// --- Text handling (from TextMessageContent) ---
const isIncoming = computed(() => props.message.isIncoming)
const linkPreviews = computed(() => {
  if (!config.settings.linkPreviewEnabled) return []
  const { urls } = props.message
  if (!urls) return []
  return urls.map((url) => imkit.linkPreviews[url]).filter((l) => l)
})
const loadingLinkPreviewUrls = computed(() => {
  if (!config.settings.linkPreviewEnabled) return []
  const { urls } = props.message
  if (!urls) return []
  const loadingSet = imkit.loadingLinkPreviews as Set<string>
  return urls.filter((url) => loadingSet.has(url) && !imkit.linkPreviews[url])
})

const html = computed((): string => {
  const keyword = imkit.messageSearchKeyword
  return highlightHtmlText(props.message.html, keyword)
})

const handleMentionClick = (event: MouseEvent) => {
  const target = event.target as HTMLElement
  if (target.tagName === 'SPAN' && target.dataset.uid) {
    const user = imkit.users[target.dataset.uid]
    if (!user) return
    const { open } = useModal({
      component: AvatarModal,
      attrs: {
        url: user.avatarUrl ?? '',
        name: user.nickname ?? ''
      }
    })
    open()
  }
}

const handleCopy = (event: ClipboardEvent) => {
  const selection = window.getSelection()
  const selectedText = selection?.toString()
  if (selectedText) {
    // User selected specific text, let the browser handle the copy natively
    return
  }
  // No selection, copy the entire message text
  event.preventDefault()
  event.clipboardData?.setData('text/plain', props.message.text)
}

const navigate = () => {
  if (!props.message.replyId) return
  imkit.navigateToMessage(props.message.replyId)
}

const failedLinkPreviewImages = ref(new Set<string>())
const handleLinkPreviewImageError = (url: string) => {
  failedLinkPreviewImages.value = new Set([
    ...failedLinkPreviewImages.value,
    url
  ])
}
const handleLinkPreviewClick = (url: string) => {
  // url is autolinked from peer-supplied message text. 'noopener,noreferrer'
  // severs window.opener (reverse tabnabbing) and the referrer.
  window.open(url, '_blank', 'noopener,noreferrer')
}

// --- Image handling (from ImageMessageContent) ---
const uploadProgresses = computed(() => imkit.uploadProgresses)

// Lightbox state
const {
  open: lightboxOpen,
  mediaIndex: lightboxIndex,
  mediaItems: previewMediaItems,
  activeMediaItem,
  selectedMedia,
  mediaCount,
  canNavigatePrevious,
  canNavigateNext,
  openMessageMedia,
  previousMedia,
  nextMedia,
  close: closeLightbox
} = useRoomMediaLightbox(() => props.message)
const selectedImage = computed(() => {
  return activeMediaItem.value?.kind === 'image'
    ? activeMediaItem.value.image
    : null
})

const calculateSize = (index: number, image: IMImage) =>
  calculateImageSize(index, image, props.message.images.length)

// Constrain root container width to match the single image's width,
// so text wraps to the image width instead of the bubble stretching.
const containerStyle = computed(() => {
  if (props.message.images.length !== 1) return {}
  const { width } = calculateImageSize(0, props.message.images[0], 1)
  // Subtract bubble padding (px-4 = 1rem × 2) so the image grid
  // (which uses -mx-4) aligns exactly to the bubble edges.
  return { width: `calc(${width} - 2rem)`, maxWidth: '100%' }
})

const showImage = (imageIndex: number) => {
  openMessageMedia(
    (item) => item.kind === 'image' && item.imageIndex === imageIndex
  )
}
</script>

<template>
  <div class="flex flex-col gap-2" :style="containerStyle">
    <!-- Reply preview (if replying). Nested quote card, replacing round 3's
         single muted line + 2px accent rule — no separate fill (card is
         transparent, shows the ambient bubble colour through), delimited
         by rounding/padding/the accent header line and, on a received
         bubble only, `border-message-border`. Identical structure and
         contrast measurements as TextMessageContent.vue's twin; see that
         file for the full derivation. -->
    <template v-if="message.replyId">
      <div
        v-if="replyMessage"
        data-testid="message-quoted"
        class="-mx-4 cursor-pointer border-b px-4 pb-1.5"
        :class="
          isIncoming ? 'border-content/8' : 'border-message-own-content/14'
        "
        @click="navigate"
      >
        <div
          class="flex items-center gap-1 text-xs font-semibold"
          :class="isIncoming ? 'text-accent-vivid' : 'text-message-own-content'"
        >
          <Reply :size="12" class="h-3 w-3 shrink-0" />
          <span data-testid="message-quoted-sender" class="truncate">
            {{ $t('reply') }} {{ replyMessageSender?.nickname }}
          </span>
        </div>
        <div
          data-testid="message-quoted-text"
          class="truncate text-xs"
          :class="
            isIncoming ? 'text-content-subtle' : 'text-message-own-content'
          "
        >
          {{ description }}
        </div>
      </div>
      <div
        v-else-if="replyUnavailable"
        data-testid="message-quoted-unavailable"
        class="-mx-4 truncate border-b px-4 pb-1.5 text-xs italic"
        :class="
          isIncoming
            ? 'border-content/8 text-content-subtle'
            : 'border-message-own-content/14 text-message-own-content'
        "
      >
        {{ $t('originalMessageUnavailable') }}
      </div>
    </template>

    <!-- Text content on top -->
    <div
      class="prose max-w-none wrap-break-word text-inherit select-none dark:prose-invert pointer-fine:select-text prose-p:leading-5.5 prose-ol:my-0"
      :class="{ 'prose-own': !isIncoming }"
      @click="handleMentionClick"
      @copy="handleCopy"
      v-html="html"
    />

    <!-- Translation -->
    <div
      v-if="isIncoming && message.translatedText"
      dir="auto"
      class="break-words text-content-subtle"
    >
      {{ $t('translation') }}: {{ message.translatedText }}
    </div>

    <!-- Link previews -->
    <div
      v-if="linkPreviews.length > 0 || loadingLinkPreviewUrls.length > 0"
      class="flex flex-col gap-3"
    >
      <!-- Skeleton loaders for loading link previews. Filled with `border`,
        the hairline token — see the fuller note on the identical skeleton in
        TextMessageContent.vue for the perceptual measurements, and for why
        contrast ratio is the wrong way to judge these bars. -->
      <div
        v-for="url in loadingLinkPreviewUrls"
        :key="url"
        class="flex animate-pulse items-stretch justify-center gap-2"
      >
        <div class="my-0.5 w-0.5 shrink-0 rounded-full bg-border" />
        <div
          class="align-center flex grow flex-col justify-center gap-1.5 overflow-hidden"
        >
          <div class="h-4 w-3/4 rounded-md bg-border" />
          <div class="h-3 w-1/2 rounded-md bg-border" />
        </div>
        <div class="my-auto h-12 w-12 shrink-0 rounded-sm bg-border" />
      </div>
      <!-- Loaded link previews -->
      <div
        v-for="linkPreview in linkPreviews"
        :key="linkPreview.url"
        class="flex cursor-pointer items-stretch justify-center gap-2"
        @click="handleLinkPreviewClick(linkPreview.url)"
      >
        <!-- Loaded-state accent bar — see the note on the identical bar in
          TextMessageContent.vue. Childless 2px stripe, no `dark:` partner;
          `accent-vivid` (the foreground/fill half of the accent split)
          clears 3:1 on every bubble in all four combinations, worst
          3.85:1. -->
        <div class="my-0.5 w-0.5 shrink-0 rounded-full bg-accent-vivid" />
        <div
          class="align-center flex grow flex-col justify-center gap-0.5 overflow-hidden"
        >
          <div class="ellipsis text-base font-bold">
            {{ linkPreview.title }}
          </div>
          <div class="multiline-ellipsis text-xs">
            {{ linkPreview.description || $t('tapOpen') }}
          </div>
        </div>
        <img
          v-if="
            linkPreview.images.length > 0 &&
            !failedLinkPreviewImages.has(linkPreview.url)
          "
          :src="linkPreview.images[0]"
          alt=""
          class="my-auto h-12 w-12 shrink-0 rounded-sm object-cover"
          @error="handleLinkPreviewImageError(linkPreview.url)"
        />
        <div
          v-else-if="failedLinkPreviewImages.has(linkPreview.url)"
          data-testid="link-preview-image-placeholder"
          aria-hidden="true"
          class="my-auto h-12 w-12 shrink-0 rounded-sm bg-content-subtle"
        />
      </div>
    </div>

    <!-- Image grid below. `-mx-4 -mb-2.5` matches the bubble wrapper's
         `px-4 py-2.5` (MessageCell.vue) exactly, so the grid's edge reaches
         the padding box and gets clipped to the bubble's own corners (20px,
         squared to 6px when grouped) by that wrapper's `overflow-hidden`,
         instead of the grid's own square corner showing inside the rounded
         bubble. Was stale `-mx-3 -mb-2` from before the wrapper moved to
         `px-4 py-2.5`, leaving a 4px/2px gap the media didn't reach. -->
    <div
      class="-mx-4 -mb-2.5 grid gap-px"
      :class="[message.images.length > 1 ? 'grid-cols-2' : 'grid-cols-1']"
    >
      <div
        v-for="(image, index) in message.images"
        :key="image.thumbnailUrl"
        class="relative flex items-center justify-center overflow-hidden"
        :class="{
          'col-span-2':
            message.images.length > 1 &&
            index === message.images.length - 1 &&
            index % 2 === 0
        }"
        @click="showImage(index)"
      >
        <MediaImg
          :url="image.thumbnailUrl"
          kind="image"
          no-callout
          img-class="border-0 object-cover transition"
          :img-style="calculateSize(index, image)"
        />
        <template
          v-if="
            image.thumbnailUrl?.startsWith('data') &&
            message.status !== MessageStatus.Failed
          "
        >
          <div class="absolute inset-0 bg-black/50" />
          <!-- ROUND 14: see FileMessageContent.vue's comment beside its own
               upload RadialProgress for the diagnosis — the stray dark
               circle behind the ring was RadialProgress's own hardcoded
               `#2F495E` track default, not this scrim (kept here: it dims a
               real photo thumbnail behind the ring). Colours match
               ImageMessageContent.vue rather than the file bubble, for the
               reason spelled out there: the ground under this ring is a
               fixed dark wash over a photo, so the ring is fixed white
               (like the `%` label) instead of following the theme. -->
          <RadialProgress
            class="absolute!"
            :diameter="56"
            :completed-steps="
              uploadProgresses[`${image.id}-thumbnail`] !== undefined
                ? (((uploadProgresses[`${image.id}-original`] ?? 0) +
                    (uploadProgresses[`${image.id}-thumbnail`] ?? 0)) /
                    2) *
                  100
                : (uploadProgresses[`${image.id}-original`] ?? 0) * 100
            "
            :total-steps="100"
            :start-color="'white'"
            :stop-color="'white'"
            :stroke-width="4"
            :inner-stroke-width="4"
            :inner-stroke-color="'rgb(255 255 255 / 0.35)'"
          >
            <span class="text-xs font-medium text-white">
              {{
                Math.round(
                  uploadProgresses[`${image.id}-thumbnail`] !== undefined
                    ? (((uploadProgresses[`${image.id}-original`] ?? 0) +
                        (uploadProgresses[`${image.id}-thumbnail`] ?? 0)) /
                        2) *
                        100
                    : (uploadProgresses[`${image.id}-original`] ?? 0) * 100
                )
              }}%
            </span>
          </RadialProgress>
        </template>
      </div>
    </div>

    <ContentLightboxDialog
      :open="lightboxOpen"
      :image="selectedImage"
      :media-items="previewMediaItems"
      :media-index="lightboxIndex"
      :selected-media="selectedMedia"
      :media-count="mediaCount"
      :can-navigate-previous="canNavigatePrevious"
      :can-navigate-next="canNavigateNext"
      :previous-media="previousMedia"
      :next-media="nextMedia"
      :room-id="message.roomId"
      @update:open="lightboxOpen = $event"
      @update:media-index="lightboxIndex = $event"
      @close="closeLightbox"
    />
  </div>
</template>

<style scoped>
.multiline-ellipsis {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}
.ellipsis {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
  overflow: hidden;
}

/* `--color-accent-vivid` is blue-500 in light and blue-400 in dark — the exact
   pair this rule used to hand-write. The token flips itself, so no dark-mode
   rule is needed. Never reintroduce one as `:global(.dark) :deep(...)`: that
   form compiles to a bare `.dark { ... }` selector (see ReactionList.vue). */
:deep(a) {
  color: var(--color-accent-vivid);
  text-decoration: underline;
  word-break: break-all;
}
:deep(code:not(pre code) a) {
  color: inherit;
  text-decoration: none;
}

/* Mirrors TextMessageContent.vue: inside an own bubble, links and @-mention
 * spans drop `--color-accent-vivid` (3.85:1 against `bg-message-own` in the
 * default light palette, under the 4.5:1 AA floor) and inherit the bubble's own
 * verified `text-message-own-content` colour instead. Links stay marked by
 * their underline, mentions by the `font-semibold` the autolinker emits. */
.prose-own :deep(a),
.prose-own :deep(span[data-uid]) {
  color: inherit;
}

:deep(li) {
  margin-top: 0;
  margin-bottom: 0;
}
:deep(ol > li)::marker,
:deep(ul > li)::marker {
  color: inherit;
}

/* Remove backticks added by Tailwind Typography prose */
:deep(code)::before,
:deep(code)::after {
  content: none;
}

/* GitHub-style inline code (exclude code blocks inside <pre>) */
:deep(code:not(pre code)) {
  display: inline;
  padding: 0.15em 0.3em;
  border-radius: 6px;
  background-color: rgba(175, 184, 193, 0.2);
  font-size: 85%;
  line-height: inherit;
  white-space: break-spaces;
  word-wrap: break-word;
  vertical-align: bottom;
}
/* No token covers this pair, so both halves stay raw — that is the sanctioned
   alternative to half-migrating. Anchored on `.prose` (this component's own
   element) rather than written as `:global(.dark) :deep(...)`, so Vue keeps the
   scope attribute on a real element instead of emitting a bare `.dark` rule. */
.dark .prose :deep(code:not(pre code)) {
  background-color: rgba(110, 118, 129, 0.4);
}
</style>
