import type ChatRoomContent from '../classes/chatRoomContent'
import { getRoomMediaFileId, type RoomMediaItem } from './roomMediaList'

export const getChatRoomContentFileExtension = (
  file: Pick<ChatRoomContent, 'fileType' | 'originalName'>
): string => {
  const name = file.originalName ?? ''
  const dot = name.lastIndexOf('.')
  return dot >= 0 ? name.slice(dot + 1) : file.fileType
}

// File creation time reflects upload completion, not the image's position in
// its message. Use message time and array order whenever that message is known.
export const indexRoomMedia = (messageMedia: readonly RoomMediaItem[]) => {
  const byFileId = new Map<
    string,
    { createdAt: number; index: number; messageId: string; mediaIndex: number }
  >()
  messageMedia.forEach((item, index) => {
    const fileId = getRoomMediaFileId(item)
    const previous = fileId ? byFileId.get(fileId) : undefined
    if (
      fileId &&
      (!previous ||
        item.createdAt > previous.createdAt ||
        (item.createdAt === previous.createdAt &&
          item.messageId > previous.messageId))
    ) {
      byFileId.set(fileId, {
        createdAt: item.createdAt,
        index,
        messageId: item.messageId,
        mediaIndex: item.kind === 'image' ? item.imageIndex : 0
      })
    }
  })
  return byFileId
}

export const getChatRoomContentMediaTime = (media: ChatRoomContent): number =>
  media.messageCreatedAt && Number.isFinite(Date.parse(media.messageCreatedAt))
    ? Date.parse(media.messageCreatedAt)
    : Number.isFinite(media.createdAtMS)
      ? media.createdAtMS
      : Date.parse(media.createdAt)

export const sortChatRoomContentMedia = (
  media: readonly ChatRoomContent[],
  messageMedia: readonly RoomMediaItem[] = [],
  sortOrder: 'asc' | 'desc' = 'asc'
): ChatRoomContent[] => {
  const byFileId = indexRoomMedia(messageMedia)
  const direction = sortOrder === 'asc' ? 1 : -1
  return [...media].sort((a, b) => {
    const aKnown = byFileId.get(a._id)
    const bKnown = byFileId.get(b._id)
    const aPosition =
      aKnown?.messageId === a.messageID ? aKnown?.mediaIndex : undefined
    const bPosition =
      bKnown?.messageId === b.messageID ? bKnown?.mediaIndex : undefined
    const aMessage = a.messageCreatedAt ? undefined : byFileId.get(a._id)
    const bMessage = b.messageCreatedAt ? undefined : byFileId.get(b._id)
    const timeDifference =
      (aMessage?.createdAt ?? getChatRoomContentMediaTime(a)) -
      (bMessage?.createdAt ?? getChatRoomContentMediaTime(b))
    const positionDifference =
      (a.mediaIndex ??
        aPosition ??
        aMessage?.index ??
        (a.messageID || a.messageCreatedAt ? 0 : Number.MAX_SAFE_INTEGER)) -
      (b.mediaIndex ??
        bPosition ??
        bMessage?.index ??
        (b.messageID || b.messageCreatedAt ? 0 : Number.MAX_SAFE_INTEGER))
    return (
      timeDifference * direction ||
      (a.messageID && b.messageID
        ? a.messageID.localeCompare(b.messageID) * direction
        : 0) ||
      positionDifference * direction ||
      ((aMessage?.index ?? Number.MAX_SAFE_INTEGER) -
        (bMessage?.index ?? Number.MAX_SAFE_INTEGER)) *
        direction
    )
  })
}
