<script lang="ts">
import { setCustomComponents, type CodeBlockNodeProps } from 'markstream-vue'
import { defineComponent, h, type PropType } from 'vue'

// Keep streamed code identical to the plain code blocks in completed messages.
// Scope the override so host applications can use Markstream independently.
const rendererId = 'imkit-ai-markdown'
setCustomComponents(rendererId, {
  code_block: defineComponent({
    inheritAttrs: false,
    props: {
      node: {
        type: Object as PropType<CodeBlockNodeProps['node']>,
        required: true
      }
    },
    setup: (props) => () => h('pre', [h('code', props.node.code)])
  })
})
</script>

<script setup lang="ts">
import MarkdownRender, { type MarkdownIt } from 'markstream-vue'
import { AIStreamingMessage } from '../classes/message'
const props = defineProps<{ message: AIStreamingMessage }>()

const BAD_URL_PROTOCOL = /^(?:vbscript|javascript|file|data):/i
const isUnsafeUrl = (url: string) => {
  const value = String(url).trim().toLowerCase()
  return BAD_URL_PROTOCOL.test(value)
}

// Streaming nodes have their own link renderer. Keep the SDK URL policy at
// the parser boundary as well as escaping raw HTML in the renderer.
const hardenMarkdown = (md: MarkdownIt) => {
  md.set({ html: false })
  md.inline.ruler2.push('imkit_safe_links', (state) => {
    for (const token of state.tokens) {
      if (token.type !== 'link_open' || !token.attrs) continue
      for (const attr of token.attrs) {
        if (attr[0] === 'href' && isUnsafeUrl(attr[1])) attr[1] = '#'
      }
    }
    // ruler2 is a post-process pass; the return is ignored by the parser.
    return false
  })
  return md
}
</script>

<template>
  <!-- WebKit fires an image error before the deferred src is assigned. Load
       images when mounted; Virtua already controls which messages mount. -->
  <MarkdownRender
    class="prose wrap-break-word select-none dark:prose-invert pointer-fine:select-text prose-headings:mt-0 prose-p:leading-5.5 prose-ol:my-0"
    :content="props.message.text"
    :custom-id="rendererId"
    :custom-markdown-it="hardenMarkdown"
    mode="chat"
    html-policy="escape"
    :typewriter="true"
    :smooth-streaming="false"
    :node-virtual="false"
    :viewport-priority="false"
  />
</template>
<style scoped>
/* MarkdownRender wraps content in node-spacer/node-slot divs, which prevents
   Tailwind prose's `:first-child { margin-top: 0 }` from reaching the <p>.
   Manually zero out the first node's top margin to match TextMessageContent. */
:deep([data-node-index='0'] > .node-content > :first-child) {
  margin-top: 0;
}

/* Chat mode omits virtual spacers. Match completed-message edge margins. */
:deep(.node-slot:only-of-type > .node-content > p),
:deep(.node-slot:last-of-type > .node-content > pre) {
  margin-bottom: 0;
}

/* MarkdownRender adds my-2 (7.5px) to list items, but TextMessageContent
   uses prose + scoped li { margin: 0 }. Match that behavior. */
:deep(li) {
  margin-top: 0;
  margin-bottom: 0;
}
:deep(ol > li)::marker,
:deep(ul > li)::marker {
  color: inherit;
}

/* MarkdownRender wraps li text in <p>, adding extra marginBottom.
   TextMessageContent li has bare text with no inner <p> margins. */
:deep(li p) {
  margin-top: 0;
  margin-bottom: 0;
}

/* `--color-accent-vivid` is blue-500 in light and blue-400 in dark — the exact
   pair this rule used to hand-write. The token flips itself, so no dark-mode
   rule is needed. Never reintroduce one as `:global(.dark) :deep(...)`: that
   form compiles to a bare `.dark { ... }` selector (see ReactionList.vue). */
:deep(a) {
  color: var(--color-accent-vivid);
  text-decoration: underline;
}
/* Remove backticks added by Tailwind Typography prose */
:deep(code)::before,
:deep(code)::after {
  content: none;
}

/* GitHub-style inline code (exclude code blocks inside <pre>) */
:deep(code:not(pre code)) {
  display: inline;
  padding: 0.15em 0.3em;
  border-radius: 6px;
  background-color: rgba(175, 184, 193, 0.2);
  font-size: 85%;
  line-height: inherit;
  white-space: break-spaces;
  word-wrap: break-word;
  vertical-align: bottom;
}
/* No token covers this pair, so both halves stay raw — that is the sanctioned
   alternative to half-migrating. Anchored on `.prose` (this component's own
   element) rather than written as `:global(.dark) :deep(...)`, so Vue keeps the
   scope attribute on a real element instead of emitting a bare `.dark` rule. */
.dark .prose :deep(code:not(pre code)) {
  background-color: rgba(110, 118, 129, 0.4);
}
</style>
