<script setup lang="ts">
import { useVfm } from 'vue-final-modal'
import { getConfig } from '../runtime/config'
import ConfirmDialogShell from './ConfirmDialogShell.vue'

const vfm = useVfm()

const handleConfirm = () => {
  // Close first so a throwing host hook can't trap the user in this
  // non-dismissible modal. Then let the host drive recovery (re-login,
  // parent postMessage, reload, ...). Optional: unset = just dismiss.
  vfm.closeAll()
  getConfig().callbacks?.onUnauthorized?.()
}
</script>

<template>
  <ConfirmDialogShell
    :title="$t('unauthorizedTitle')"
    :confirm-label="$t('confirm', '確定')"
    confirm-variant="primary"
    :click-to-close="false"
    :esc-to-close="false"
    @confirm="handleConfirm"
  >
    {{ $t('unauthorizedMessage') }}
  </ConfirmDialogShell>
</template>
