import { useImkitStore } from '../stores/imkit'

// action.uri comes from server-supplied LINE template data, so it is
// attacker-influenced. Reject by default and only open well-known safe schemes
// — a dangerous scheme (javascript:, data:, vbscript:, file:, …) handed to
// window.open can execute script or load hostile content in this origin.
// 'line:' is a documented LINE URI-action deep-link scheme; it cannot execute
// script in our origin, so it stays on the allowlist.
const SAFE_URI_PROTOCOLS = new Set([
  'http:',
  'https:',
  'tel:',
  'mailto:',
  'line:'
])
const isSafeUri = (uri: string): boolean => {
  try {
    return SAFE_URI_PROTOCOLS.has(new URL(uri).protocol)
  } catch {
    return false
  }
}

export default (
  roomId: string,
  action?: {
    type: string
    label: string
    uri: string
    text: string
  }
) => {
  // action is optional at runtime: a template's defaultAction can be omitted
  // (optional in the LINE spec), and a malformed template falls back to {} so
  // template.defaultAction is undefined. Call sites bind it straight to @click,
  // so guard here to cover every caller — a bare switch on undefined.type would
  // throw inside the click handler.
  if (!action) return
  switch (action.type) {
    case 'message': {
      const payload = {
        roomId,
        messageType: 'text',
        message: action.text
      }
      useImkitStore().sendMessage(payload)
      break
    }
    case 'uri':
      if (isSafeUri(action.uri)) {
        // 'noopener,noreferrer' severs window.opener to block reverse tabnabbing.
        window.open(action.uri, '_blank', 'noopener,noreferrer')
      } else {
        console.error(`Blocked unsafe action URI: ${action.uri}`)
      }
      break
    default:
      console.error(`Unsupported action type: ${action.type}`)
      break
  }
}
