function isWide(codePoint: number): boolean {
  let lo = 0
  let hi = EAST_ASIAN_WIDE_RANGES.length - 1
  while (lo <= hi) {
    const mid = (lo + hi) >> 1
    const [start, end] = EAST_ASIAN_WIDE_RANGES[mid]
    if (codePoint < start) {
      hi = mid - 1
    } else if (codePoint > end) {
      lo = mid + 1
    } else {
      return true
    }
  }
  return false
}

/** A wide/fullwidth codepoint counts as 2 display-width units, everything
 * else (including narrow Latin, combining marks, ASCII) counts as 1. */
export function charDisplayWidth(char: string): 1 | 2 {
  const codePoint = char.codePointAt(0) ?? 0
  return isWide(codePoint) ? 2 : 1
}

export function displayWidth(text: string): number {
  let width = 0
  for (const char of text) {
    width += charDisplayWidth(char)
  }
  return width
}

/**
 * Middle-truncates `text` to the first `headUnits` display-width units, an
 * ellipsis, and the last `tailUnits` display-width units — but only when
 * `text`'s total display width exceeds `headUnits + tailUnits`. A wide
 * character that would straddle a boundary (push the running width over the
 * budget) is excluded rather than split.
 */
export function middleTruncateByDisplayWidth(
  text: string,
  headUnits = 13,
  tailUnits = 7
): string {
  const chars = Array.from(text)
  const widths = chars.map(charDisplayWidth)
  const total = widths.reduce((sum, w) => sum + w, 0)
  if (total <= headUnits + tailUnits) {
    return text
  }

  let head = ''
  let headWidth = 0
  let i = 0
  for (; i < chars.length; i++) {
    const w = widths[i]
    if (headWidth + w > headUnits) break
    head += chars[i]
    headWidth += w
  }

  let tail = ''
  let tailWidth = 0
  for (let j = chars.length - 1; j >= i; j--) {
    const w = widths[j]
    if (tailWidth + w > tailUnits) break
    tail = chars[j] + tail
    tailWidth += w
  }

  return `${head}…${tail}`
}
