const MAX_CACHE_BYTES = 64 * 1024 * 1024

const blobCache = new Map<string, Blob>()
const pendingRequests = new Map<string, Promise<Blob>>()
let cacheBytes = 0
let cacheGeneration = 0

const getCachedBlob = (url: string): Blob | null => {
  const cached = blobCache.get(url)
  if (!cached) return null

  blobCache.delete(url)
  blobCache.set(url, cached)
  return cached
}

const cacheBlob = (url: string, blob: Blob): void => {
  if (blob.size > MAX_CACHE_BYTES) return

  while (cacheBytes + blob.size > MAX_CACHE_BYTES && blobCache.size > 0) {
    const oldestUrl = blobCache.keys().next().value
    if (oldestUrl === undefined) break
    const oldestBlob = blobCache.get(oldestUrl)
    if (oldestBlob) cacheBytes -= oldestBlob.size
    blobCache.delete(oldestUrl)
  }

  blobCache.set(url, blob)
  cacheBytes += blob.size
}

export const resolveVideoBlob = (
  url: string,
  loader: () => Promise<Blob>
): Promise<Blob> => {
  const cached = getCachedBlob(url)
  if (cached) return Promise.resolve(cached)

  const pending = pendingRequests.get(url)
  if (pending) return pending

  const generation = cacheGeneration
  const request = Promise.resolve()
    .then(loader)
    .then((blob) => {
      if (generation === cacheGeneration) cacheBlob(url, blob)
      return blob
    })
    .finally(() => {
      if (pendingRequests.get(url) === request) {
        pendingRequests.delete(url)
      }
    })
  pendingRequests.set(url, request)
  return request
}

export const clearVideoBlobCache = (): void => {
  cacheGeneration += 1
  pendingRequests.clear()
  blobCache.clear()
  cacheBytes = 0
}

export const _resetVideoBlobStoreForTests = clearVideoBlobCache
