import axiosModule, { type AxiosInstance, type AxiosProgressEvent } from 'axios'

export const fetchImageAsBase64 = async (
  url: string,
  onProgress?: (ratio: number) => void
): Promise<string> => {
  // Use the plain axios module (no interceptors) so we don't attach
  // IM-Authorization / IM-Client-Key headers, which would trigger a CORS
  // preflight against S3/GCS signed URLs.
  const resp = await axiosModule.get(url, {
    responseType: 'arraybuffer',
    onDownloadProgress: (e: AxiosProgressEvent) => {
      if (e.total) onProgress?.(e.loaded / e.total)
    }
  })
  // Convert in fixed 0x8000-byte windows via String.fromCharCode(...subarray)
  // instead of one call per byte: the per-byte reduce built an O(n) string with
  // O(n) intermediate concatenations and 40k+ function calls on the main thread
  // for a modest image, stalling decode of large media.
  const bytes = new Uint8Array(resp.data)
  let binary = ''
  for (let index = 0; index < bytes.length; index += 0x8000) {
    binary += String.fromCharCode(...bytes.subarray(index, index + 0x8000))
  }
  return `data:${resp.headers['content-type']};base64,${btoa(binary)}`
}

export const refreshS3PresignedUrl = async (
  axios: AxiosInstance,
  s3Url: string
): Promise<string | null> => {
  const { hostname, pathname } = new URL(s3Url)
  if (!hostname.includes('s3') || !hostname.includes('amazonaws.com')) {
    return null
  }
  const segments = pathname.split('/').filter(Boolean)
  if (segments.length < 3) return null
  // S3 path: /{appPrefix}/{bucketName}/{fileId}
  const { data } = await axios.get(
    `/files/${segments[1]}/${segments.slice(2).join('/')}?signedUrlOnly=true`
  )
  return data.result?.url ?? null
}

export const resolveFilesProxyUrl = async (
  axios: AxiosInstance,
  url: string
): Promise<string | null> => {
  let pathname: string
  try {
    pathname = url.startsWith('http') ? new URL(url).pathname : url
  } catch {
    return null
  }
  const match = pathname.match(/^\/files\/([^/]+)\/(.+)$/)
  if (!match) return null
  const [, bucketName, fileId] = match
  const { data } = await axios.get(
    `/files/${bucketName}/${fileId}?signedUrlOnly=true`
  )
  return data.result?.url ?? null
}
