import { escapeRegExp } from './escapeRegExp'

export function highlightHtmlText(html: string, keyword: string): string {
  if (!keyword) return html
  const template = document.createElement('template')
  template.innerHTML = html
  const regex = new RegExp(
    `(?<![a-zA-Z0-9_])${escapeRegExp(keyword)}(?![a-zA-Z0-9_])`,
    'giu'
  )
  const walker = document.createTreeWalker(
    template.content,
    NodeFilter.SHOW_TEXT
  )
  const nodes: Text[] = []
  while (walker.nextNode()) nodes.push(walker.currentNode as Text)
  let changed = false
  for (const node of nodes) {
    const parts = node.data.split(regex)
    const matches = node.data.match(regex)
    if (!matches) continue
    changed = true
    const fragment = document.createDocumentFragment()
    parts.forEach((part, index) => {
      fragment.append(document.createTextNode(part))
      const match = matches[index]
      if (match) {
        const span = document.createElement('span')
        span.className = 'bg-highlight text-highlight-content'
        span.textContent = match
        fragment.append(span)
      }
    })
    node.replaceWith(fragment)
  }
  // No text node matched: return the original string untouched rather than the
  // browser's reserialized innerHTML, preserving byte-identical output on no-match.
  return changed ? template.innerHTML : html
}
