import { onMounted, onUnmounted, watch, type Ref } from 'vue'
import { registerPortalPaletteSource } from '../runtime/portalHost'
import { applyPalette } from '../runtime/theme'

/**
 * Applies the public design palette to an SDK root and mirrors it to portals.
 * The consumer remains responsible for binding the root's `dark` class.
 */
export function useDesignPalette(
  root: Readonly<Ref<HTMLElement | null>>,
  dark: Readonly<Ref<boolean>>
): void {
  let activeRoot: HTMLElement | null = null
  let unregisterPortalSource: (() => void) | null = null

  const sync = () => {
    const nextRoot = root.value
    if (!nextRoot) {
      unregisterPortalSource?.()
      unregisterPortalSource = null
      activeRoot = null
      return
    }

    applyPalette(nextRoot, dark.value)
    if (nextRoot === activeRoot) return

    unregisterPortalSource?.()
    activeRoot = nextRoot
    unregisterPortalSource = registerPortalPaletteSource(nextRoot)
  }

  watch([root, dark], sync, { flush: 'post' })
  onMounted(sync)
  onUnmounted(() => {
    unregisterPortalSource?.()
    unregisterPortalSource = null
    activeRoot = null
  })
}
