<script setup lang="ts">
import { computed } from 'vue'
import { safeColor, safeLen } from '../utils/safeStyle'
import FlexMessageComponent from './FlexMessageComponent.vue'

const MAX_FLEX_DEPTH = 20
const MAX_FLEX_CHILDREN = 200

/* eslint-disable @typescript-eslint/no-explicit-any */
const props = withDefaults(
  defineProps<{ content: any; roomId?: string; depth?: number }>(),
  {
    roomId: '',
    depth: 0
  }
)
/* eslint-enable @typescript-eslint/no-explicit-any */

const shouldRender = computed(() => props.depth < MAX_FLEX_DEPTH)

const children = computed(() =>
  Array.isArray(props.content.contents)
    ? props.content.contents.slice(0, MAX_FLEX_CHILDREN)
    : []
)

const transformSize = (size: string) => {
  const sizes: { [size: string]: string } = {
    none: '0',
    xs: '2px',
    sm: '4px',
    md: '8px',
    lg: '12px',
    xl: '16px',
    xxl: '20px'
  }
  // Named scale values are our own safe constants; any other value is a
  // peer-controlled raw length and must pass safeLen — otherwise margin/spacing
  // becomes an inline-style sink that bypasses the width/height hardening
  // (e.g. margin:'100vw' or 'calc(...)' escaping the bubble bounds).
  return sizes[size] ?? safeLen(size)
}
</script>

<template>
  <div
    v-if="shouldRender"
    class="flex"
    :class="{
      'flex-col': content.layout === 'vertical',
      'flex-row': content.layout === 'horizontal',
      'flex-row items-baseline': content.layout === 'baseline'
    }"
    :style="{
      overflow: 'hidden',
      backgroundColor: safeColor(content.backgroundColor) ?? '#00000000',
      borderColor: safeColor(content.borderColor),
      borderWidth: safeLen(content.borderWidth),
      borderRadius: safeLen(content.cornerRadius),
      width: safeLen(content.width),
      maxWidth: safeLen(content.maxWidth),
      height: safeLen(content.height),
      maxHeight: safeLen(content.maxHeight)
    }"
  >
    <flex-message-component
      v-for="(c, index) in children"
      :key="index"
      :content="c"
      :room-id="roomId"
      :depth="depth + 1"
      :style="
        content.layout === 'vertical'
          ? {
              marginTop: c.margin
                ? transformSize(c.margin)
                : index === 0
                  ? 0
                  : transformSize(content.spacing)
            }
          : {
              marginLeft: c.margin
                ? transformSize(c.margin)
                : index === 0
                  ? 0
                  : transformSize(content.spacing)
            }
      "
    />
  </div>
</template>

<style scoped></style>
