<template>
  <Dialog :open="dialogOpen" @update:open="handleOpenChange">
    <DialogContent
      class="flex h-dvh w-dvw max-w-none flex-col !rounded-none !bg-[#000] !p-3 md:h-[90vh] md:max-w-5xl md:!rounded-lg md:!p-0"
      :hide-close="true"
    >
      <DialogTitle class="sr-only">
        {{
          isVideoMode ||
          isDirectVideoMode ||
          selectedMedia?.fileType === 'video'
            ? $t('video')
            : $t('image')
        }}
      </DialogTitle>
      <DialogDescription class="sr-only">
        {{
          senderName ||
          (isVideoMode ||
          isDirectVideoMode ||
          selectedMedia?.fileType === 'video'
            ? $t('video')
            : $t('image'))
        }}
      </DialogDescription>
      <div
        data-id="content-lightbox-dialog-header"
        class="flex shrink-0 items-baseline justify-between px-2 py-2 md:rounded-t-lg md:px-4 md:py-3"
      >
        <template v-if="showDownload">
          <Loader2
            v-if="downloadLoading"
            class="h-5 w-5 animate-spin text-white"
          />
          <Download
            v-else
            class="h-5 w-5 cursor-pointer text-white"
            @click="handleDownload"
          />
        </template>
        <div v-else class="h-5 w-5" />
        <div v-if="showHeader" class="flex-1 text-center text-white">
          <div class="space-y-0.5 text-xs">
            <div>{{ senderName }}</div>
            <div>{{ dayjs(createdAt).format('YYYY-MM-DD') }}</div>
          </div>
        </div>
        <div v-else class="flex-1" />
        <DialogClose
          class="cursor-pointer text-white opacity-70 transition-opacity hover:opacity-100"
        >
          <X class="h-5 w-5" />
        </DialogClose>
      </div>
      <div
        data-id="content-lightbox-dialog-content"
        class="relative isolate flex min-h-0 flex-1 flex-col overflow-hidden md:rounded-b-lg"
      >
        <div
          class="relative z-0 flex h-full flex-1 items-center justify-center bg-black/95"
        >
          <!-- ChatRoomContent mode (presigned URL) -->
          <template v-if="isRoomContentMode">
            <template
              v-if="
                selectedMedia &&
                selectedMedia.fileType === 'image' &&
                presignedUrl
              "
            >
              <div
                ref="imageZoomContainer"
                data-id="content-lightbox-image-zoom"
                :data-zoom-scale="imageScale"
                class="relative flex h-full w-full touch-none items-center justify-center overflow-hidden select-none"
                :class="{
                  'cursor-grab': isImageZoomed && !imageZoomInteracting,
                  'cursor-grabbing': imageZoomInteracting
                }"
                @dblclick.stop="onImageDoubleClick"
                @pointercancel.stop="onImagePointerCancel"
                @pointerdown.stop="onImagePointerDown"
                @pointermove.stop="onImagePointerMove"
                @pointerup.stop="onImagePointerUp"
              >
                <img
                  :src="presignedUrl"
                  :alt="$t('image')"
                  :style="imageZoomStyle"
                  :draggable="false"
                  :class="imagePreviewClass"
                />
              </div>
            </template>
            <template v-else>
              <video
                v-if="selectedMedia && presignedUrl"
                :src="presignedUrl"
                controls
                class="h-auto max-h-[85vh] w-auto max-w-full md:max-h-[75vh]"
                autoplay
              />
            </template>
          </template>

          <!-- IMImage mode -->
          <template v-else-if="isImageMode && image">
            <div
              ref="imageZoomContainer"
              data-id="content-lightbox-image-zoom"
              :data-zoom-scale="imageScale"
              class="relative flex h-full w-full touch-none items-center justify-center overflow-hidden select-none"
              :class="{
                'cursor-grab': isImageZoomed && !imageZoomInteracting,
                'cursor-grabbing': imageZoomInteracting
              }"
              @dblclick.stop="onImageDoubleClick"
              @pointercancel.stop="onImagePointerCancel"
              @pointerdown.stop="onImagePointerDown"
              @pointermove.stop="onImagePointerMove"
              @pointerup.stop="onImagePointerUp"
            >
              <!-- Thumbnail: shown only while original is still loading -->
              <MediaImg
                v-if="
                  !originalImageLoaded &&
                  !originalImageFailed &&
                  image.thumbnailUrl !== image.originalUrl
                "
                :url="image.thumbnailUrl"
                :img-style="imageZoomStyle"
                :no-callout="true"
                kind="image"
                variant="thumb"
                data-id="thumbnail-url"
                :img-class="imagePreviewClass"
              />
              <!-- Original image (or same as thumbnail when URLs match) -->
              <MediaImg
                :url="image.originalUrl"
                :img-style="imageZoomStyle"
                :no-callout="true"
                kind="image"
                variant="full"
                data-id="original-url"
                :img-class="
                  [
                    imagePreviewClass,
                    !originalImageLoaded &&
                    !originalImageFailed &&
                    image.thumbnailUrl !== image.originalUrl
                      ? 'invisible absolute'
                      : ''
                  ].join(' ')
                "
                @load="originalImageLoaded = true"
                @error="originalImageFailed = true"
                @retry="originalImageFailed = false"
              />
              <template
                v-if="
                  (!downloadProgresses[image.originalUrl] ||
                    downloadProgresses[image.originalUrl] < 1) &&
                  image.thumbnailUrl !== image.originalUrl &&
                  !originalImageLoaded &&
                  !originalImageFailed
                "
              >
                <div class="absolute inset-0 bg-black/50" />
                <!--
                  White, matching every other ring that sits on a media scrim
                  (Image/Video/MixedMessageContent). It has to read against an
                  arbitrary photo in both colour modes, and white is unchanged.
                  Only FileMessageContent's ring takes accent, because that one
                  sits on a message bubble rather than a photo.

                  Was a hardcoded `#60a5fa`, which is off-palette and would not
                  follow a palette change. These are props rather than classes
                  because RadialProgress writes them onto SVG presentation
                  attributes, which no class can reach.
                -->
                <RadialProgress
                  class="absolute!"
                  :diameter="40"
                  :completed-steps="
                    (downloadProgresses[image.originalUrl] ?? 0) * 100
                  "
                  :total-steps="100"
                  :start-color="'white'"
                  :stop-color="'white'"
                  :inner-stroke-color="'rgb(255 255 255 / 0.35)'"
                  :stroke-width="4"
                  :inner-stroke-width="4"
                />
              </template>
            </div>
          </template>

          <!-- IMVideo mode -->
          <template v-else-if="isVideoMode && video">
            <template v-if="videoLoading">
              <div class="flex h-[50vh] items-center justify-center">
                <Loader2 class="h-10 w-10 animate-spin text-white" />
              </div>
            </template>
            <template v-else-if="videoUrl">
              <video
                :src="videoUrl"
                class="h-auto max-h-[85vh] w-auto max-w-full md:max-h-[75vh]"
                controls
                autoplay
              />
            </template>
          </template>

          <!-- Direct video URL mode (local file preview) -->
          <template v-else-if="isDirectVideoMode && directVideoUrl">
            <video
              :src="directVideoUrl"
              class="h-auto max-h-[85vh] w-auto max-w-full md:max-h-[75vh]"
              controls
              autoplay
            />
          </template>
        </div>

        <!-- Navigation arrows -->
        <div
          class="pointer-events-none absolute inset-x-0 top-1/2 z-10 flex -translate-y-1/2 justify-between px-2 md:px-4"
        >
          <button
            v-if="mediaCount > 1"
            type="button"
            data-testid="media-previous"
            :aria-label="$t('previous')"
            :aria-busy="navigationPending"
            :disabled="navigationPending || !canNavigatePrevious"
            class="pointer-events-auto inline-flex h-11 w-11 items-center justify-center gap-2 !rounded-full rounded-md bg-black/50 text-base font-medium whitespace-nowrap text-white transition-colors duration-200 focus-visible:ring-2 focus-visible:ring-white focus-visible:ring-offset-2 focus-visible:ring-offset-black"
            :class="
              navigationPending || !canNavigatePrevious
                ? 'cursor-not-allowed opacity-30'
                : 'cursor-pointer hover:bg-black/70'
            "
            @click="previousMedia"
          >
            <ChevronLeft class="h-7 w-7" />
          </button>
          <button
            v-if="mediaCount > 1"
            type="button"
            data-testid="media-next"
            :aria-label="$t('next')"
            :aria-busy="navigationPending"
            :disabled="navigationPending || !canNavigateNext"
            class="pointer-events-auto inline-flex h-11 w-11 items-center justify-center gap-2 !rounded-full rounded-md bg-black/50 text-base font-medium whitespace-nowrap text-white transition-colors duration-200 focus-visible:ring-2 focus-visible:ring-white focus-visible:ring-offset-2 focus-visible:ring-offset-black"
            :class="
              navigationPending || !canNavigateNext
                ? 'cursor-not-allowed opacity-30'
                : 'cursor-pointer hover:bg-black/70'
            "
            @click="nextMedia"
          >
            <ChevronRight class="h-7 w-7" />
          </button>
        </div>
      </div>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import dayjs from 'dayjs'
import {
  ChevronLeft,
  ChevronRight,
  Download,
  Loader2,
  X
} from 'lucide-vue-next'
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import RadialProgress from 'vue3-radial-progress'
import ChatRoomContent from '../../classes/chatRoomContent'
import IMImage from '../../classes/image'
import IMVideo from '../../classes/video'
import {
  MIME_TYPES,
  useMediaDownload
} from '../../composables/useMediaDownload'
import { useImageZoom } from '../../composables/useImageZoom'
import { useImkitStore } from '../../stores/imkit'
import { extractFileIdFromUrl } from '../../utils/fileUrl'
import type { RoomMediaItem } from '../../utils/roomMediaList'
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogTitle
} from './dialog'
import MediaImg from './MediaImg.vue'

// Keep the fit stable when message navigation switches to File API media.
const imagePreviewClass =
  'h-auto max-h-[85vh] w-full max-w-[95vw] object-contain md:max-h-[75vh] md:max-w-[90vw]'

const imkit = useImkitStore()
const { downloadProgresses, download } = useMediaDownload()

// Local loading state for download button (covers fetchSignedUrl + download)
const downloadLoading = ref(false)

defineOptions({
  name: 'ContentLightboxDialog'
})

const props = withDefaults(
  defineProps<{
    open?: boolean
    // ChatRoomContent mode
    selectedMedia?: ChatRoomContent | null
    previousMedia?: () => void | Promise<void>
    nextMedia?: () => void | Promise<void>
    mediaCount?: number
    canNavigatePrevious?: boolean | null
    canNavigateNext?: boolean | null
    // Loaded message media mode
    mediaItems?: readonly RoomMediaItem[]
    mediaIndex?: number
    // IMImage/IMVideo mode
    image?: IMImage | null
    video?: IMVideo | null
    // Direct video URL mode (for local file preview)
    directVideoUrl?: string | null
    // Room ID for fetching signed URL (used in IMImage/IMVideo mode)
    roomId?: string | null
    // Header info (used in all modes)
    senderName?: string | null
    createdAt?: string | number | null
    // UI options
    showDownload?: boolean
  }>(),
  {
    open: false,
    selectedMedia: null,
    previousMedia: undefined,
    nextMedia: undefined,
    mediaCount: 0,
    canNavigatePrevious: null,
    canNavigateNext: null,
    mediaItems: () => [],
    mediaIndex: 0,
    image: null,
    video: null,
    directVideoUrl: null,
    roomId: null,
    senderName: null,
    createdAt: null,
    showDownload: true
  }
)

const emit = defineEmits<{
  (e: 'update:open', value: boolean): void
  (e: 'update:mediaIndex', value: number): void
  (e: 'close'): void
}>()

// Mode detection
const activeMediaItem = computed(
  () => props.mediaItems[props.mediaIndex] ?? null
)
const image = computed(() => {
  const item = activeMediaItem.value
  if (item) return item.kind === 'image' ? item.image : null
  return props.image
})
const video = computed(() => {
  const item = activeMediaItem.value
  if (item) return item.kind === 'video' ? item.video : null
  return props.video
})
const roomId = computed(() => activeMediaItem.value?.roomId ?? props.roomId)
const senderName = computed(
  () =>
    props.selectedMedia?.client?.nickname ??
    activeMediaItem.value?.senderName ??
    props.senderName
)
const createdAt = computed(
  () =>
    props.selectedMedia?.createdAt ??
    activeMediaItem.value?.createdAt ??
    props.createdAt
)
const mediaCount = computed(() =>
  props.mediaCount > 0 ? props.mediaCount : props.mediaItems.length
)
const canNavigatePrevious = computed(
  () =>
    mediaCount.value > 1 &&
    (props.canNavigatePrevious ??
      (props.mediaItems.length > 0 ? props.mediaIndex > 0 : true))
)
const canNavigateNext = computed(
  () =>
    mediaCount.value > 1 &&
    (props.canNavigateNext ??
      (props.mediaItems.length > 0
        ? props.mediaIndex < props.mediaItems.length - 1
        : true))
)
const isRoomContentMode = computed(() => {
  const media = props.selectedMedia
  if (!media) return false
  // File API metadata arrives after the message preview opens. Keep the
  // existing image mounted when it describes the same file; switching to a
  // new <img> here discards the thumbnail while the original is still loading.
  return !(
    media.fileType === 'image' &&
    image.value &&
    extractFileIdFromUrl(image.value.originalUrl) === media._id
  )
})
const isImageMode = computed(() => Boolean(image.value))
const isVideoMode = computed(() => Boolean(video.value))
const isDirectVideoMode = computed(() => Boolean(props.directVideoUrl))
const showHeader = computed(
  () => isRoomContentMode.value || Boolean(senderName.value)
)

// ChatRoomContent mode state
const presignedUrl = ref<string | null>(null)
const dialogOpen = computed(() => props.open)
const imageZoomContainer = ref<HTMLElement | null>(null)
const {
  imageStyle: imageZoomStyle,
  isInteracting: imageZoomInteracting,
  isZoomed: isImageZoomed,
  onDoubleClick: onImageDoubleClick,
  onPointerCancel: onImagePointerCancel,
  onPointerDown: onImagePointerDown,
  onPointerMove: onImagePointerMove,
  onPointerUp: onImagePointerUp,
  reset: resetImageZoom,
  scale: imageScale
} = useImageZoom(imageZoomContainer)

// IMImage mode state
const originalImageLoaded = ref(false)
const originalImageFailed = ref(false)
watch([() => props.open, image, isRoomContentMode], () => {
  originalImageLoaded.value = false
  originalImageFailed.value = false
})

// IMVideo mode state
const videoUrl = ref<string | null>(null)
const videoLoading = ref(false)
const navigationPending = ref(false)
let navigationGeneration = 0

const invalidateNavigation = () => {
  navigationGeneration += 1
  navigationPending.value = false
}

const handleOpenChange = (value: boolean) => {
  emit('update:open', value)
  if (!value) {
    invalidateNavigation()
    resetImageZoom()
    emit('close')
    // Cleanup video blob URL
    if (videoUrl.value) {
      URL.revokeObjectURL(videoUrl.value)
      videoUrl.value = null
    }
  }
}

// ChatRoomContent: fetch presigned URL
const fetchPresigned = async () => {
  const media = props.selectedMedia
  if (!media) return
  const currentId = media._id
  try {
    const url = await imkit.fetchPresignedUrl({
      bucketName: media.room || '',
      fileId: media._id || ''
    })
    // Check if media changed during async operation
    if (props.selectedMedia?._id !== currentId) return
    presignedUrl.value = (url as string) || null
  } catch (err) {
    console.error('[Lightbox] fetchPresignedUrl error:', err)
    if (props.selectedMedia?._id === currentId) {
      presignedUrl.value = null
    }
  }
}

// IMVideo: load video blob. The generation prevents a request started by a
// closed or previous lightbox view from creating an orphaned object URL.
let videoLoadGeneration = 0
const loadVideo = async (generation: number) => {
  const selectedVideo = video.value
  if (!selectedVideo || videoUrl.value) return
  const currentId = selectedVideo.id
  const isCurrentLoad = () =>
    generation === videoLoadGeneration &&
    props.open &&
    video.value?.id === currentId
  videoLoading.value = true
  try {
    const blob = await imkit.fetchVideoBlob(selectedVideo.originalUrl)
    if (!isCurrentLoad()) return
    videoUrl.value = URL.createObjectURL(blob)
  } catch (error) {
    if (isCurrentLoad()) {
      console.error('[Lightbox] loadVideo error:', error)
    }
  } finally {
    if (isCurrentLoad()) {
      videoLoading.value = false
    }
  }
}

// Fetch signed URL for IMImage/IMVideo mode
const fetchSignedUrl = async (originalUrl: string): Promise<string | null> => {
  if (!roomId.value) return null
  const fileId = extractFileIdFromUrl(originalUrl)
  if (!fileId) return null
  try {
    const url = await imkit.fetchPresignedUrl({
      bucketName: roomId.value,
      fileId
    })
    return (url as string) || null
  } catch (err) {
    console.error('[Lightbox] fetchSignedUrl error:', err)
    return null
  }
}

// Download handler
const handleDownload = async () => {
  if (downloadLoading.value) return
  downloadLoading.value = true

  try {
    if (isRoomContentMode.value && props.selectedMedia && presignedUrl.value) {
      const isImage = props.selectedMedia.fileType === 'image'
      const url = `/files/${props.selectedMedia.room}/${props.selectedMedia._id}`
      const signedUrl = await imkit.fetchPresignedUrl({
        bucketName: props.selectedMedia.room,
        fileId: props.selectedMedia._id
      })
      await download({
        url,
        fileName: props.selectedMedia.originalName,
        fallbackId: props.selectedMedia._id,
        mimeType:
          props.selectedMedia.mimetype ||
          (isImage ? MIME_TYPES.IMAGE_JPEG : MIME_TYPES.VIDEO_MP4),
        useSignedUrl: true,
        signedUrl: signedUrl || undefined
      })
    } else if (isImageMode.value && image.value) {
      // Fetch signed URL for image download (needed for cross-origin/iframe)
      const signedUrl = await fetchSignedUrl(image.value.originalUrl)
      await download({
        url: image.value.originalUrl,
        fallbackId: image.value.id,
        mimeType: MIME_TYPES.IMAGE_JPEG,
        useSignedUrl: true,
        signedUrl: signedUrl || undefined
      })
    } else if (isVideoMode.value && video.value) {
      // Fetch signed URL for video download
      const signedUrl = await fetchSignedUrl(video.value.originalUrl)
      await download({
        url: video.value.originalUrl,
        fallbackId: video.value.id,
        mimeType: MIME_TYPES.VIDEO_MP4,
        useSignedUrl: true,
        signedUrl: signedUrl || undefined
      })
    }
  } catch (error) {
    // download() now rejects when a cross-origin blob fetch fails and the
    // fallback popup is blocked. The calls above are awaited, so catch here
    // instead of leaking an unhandled rejection out of the click handler.
    console.error('[Lightbox] download failed:', error)
  } finally {
    downloadLoading.value = false
  }
}

// Watch for open state changes
watch(
  [() => props.open, () => props.selectedMedia, image, video],
  ([open, media, , selectedVideo]) => {
    const generation = ++videoLoadGeneration
    if (!open) invalidateNavigation()
    presignedUrl.value = null
    videoLoading.value = false
    if (videoUrl.value) {
      URL.revokeObjectURL(videoUrl.value)
      videoUrl.value = null
    }

    if (open) {
      if (media && isRoomContentMode.value) {
        void fetchPresigned()
      } else if (selectedVideo) {
        void loadVideo(generation)
      }
    }
  },
  { immediate: true }
)

const zoomMediaIdentity = computed(() => {
  if (props.selectedMedia) return `content:${props.selectedMedia._id}`
  if (activeMediaItem.value) return `item:${activeMediaItem.value.key}`
  if (props.image) return `image:${props.image.id}`
  return null
})

watch(
  [() => props.open, zoomMediaIdentity],
  () => {
    resetImageZoom()
  },
  { flush: 'sync' }
)

const handleKeydown = (event: KeyboardEvent) => {
  if (!props.open || mediaCount.value <= 1) return

  if (event.key === 'ArrowLeft' && canNavigatePrevious.value) {
    event.preventDefault()
    previousMedia()
  } else if (event.key === 'ArrowRight' && canNavigateNext.value) {
    event.preventDefault()
    nextMedia()
  }
}

onMounted(() => {
  window.addEventListener('keydown', handleKeydown)
})

onUnmounted(() => {
  videoLoadGeneration += 1
  invalidateNavigation()
  window.removeEventListener('keydown', handleKeydown)
  // Cleanup video blob URL on unmount
  if (videoUrl.value) {
    URL.revokeObjectURL(videoUrl.value)
  }
})

const runNavigation = async (
  canNavigate: boolean,
  externalNavigation: (() => void | Promise<void>) | undefined,
  fallbackIndex: () => number
) => {
  if (!canNavigate || navigationPending.value) return
  resetImageZoom()
  const generation = navigationGeneration
  navigationPending.value = true
  try {
    if (externalNavigation) {
      const result = externalNavigation()
      if (result) await result
    } else if (props.mediaItems.length > 1) {
      emit('update:mediaIndex', fallbackIndex())
    }
  } catch (error) {
    console.error('[Lightbox] navigation failed:', error)
  } finally {
    if (generation === navigationGeneration) {
      navigationPending.value = false
    }
  }
}

const previousMedia = () =>
  runNavigation(
    canNavigatePrevious.value,
    props.previousMedia,
    () => props.mediaIndex - 1
  )

const nextMedia = () =>
  runNavigation(
    canNavigateNext.value,
    props.nextMedia,
    () => props.mediaIndex + 1
  )
</script>
