<script setup lang="ts">
import dayjs from 'dayjs'
import { AlertTriangle, Loader2 } from 'lucide-vue-next'
import { MessageStatus } from '../classes/message'
import { RoomType } from '../classes/room'

defineProps<{
  direction: 'outgoing' | 'incoming'
  showLoading: boolean
  status: MessageStatus
  isEdited: boolean
  createdAt: number
  numberOfRead: number
  enableReadReceipt: boolean
  roomType: RoomType
}>()

const emit = defineEmits<{
  showActions: []
}>()
</script>

<template>
  <!-- Outgoing: 非尾端訊息的狀態 -->
  <div
    v-if="direction === 'outgoing'"
    class="flex flex-col items-end self-end-safe text-xs text-content-subtle"
  >
    <div v-if="enableReadReceipt && numberOfRead > 0">
      {{ $t('read') }}
      <template v-if="roomType === RoomType.Group">
        {{ numberOfRead }}
      </template>
    </div>
    <div>
      <Loader2
        v-if="showLoading"
        class="mr-1 mb-0.5 inline h-3 w-3 animate-spin"
      />
      <AlertTriangle
        v-else-if="status === MessageStatus.Failed"
        class="mr-1 mb-0.5 inline h-4 w-4 cursor-pointer text-danger-vivid"
        @click="emit('showActions')"
      />
      <span v-if="isEdited" class="mr-1 text-content-faint">{{
        $t('edited')
      }}</span>
      {{ dayjs(createdAt).format('H:mm') }}
    </div>
  </div>

  <!-- Incoming: 時間顯示 -->
  <div v-else class="self-end text-xs text-content-subtle">
    <span v-if="isEdited" class="mr-1 text-content-faint">{{
      $t('edited')
    }}</span>
    {{ dayjs(createdAt).format('H:mm') }}
  </div>
</template>
