<script setup lang="ts">
import {
  Check,
  ChevronDown,
  FolderPlus,
  Megaphone,
  Plus
} from 'lucide-vue-next'
import { isDark } from 'vue-dark-switch'
import HeaderDivider from './HeaderDivider.vue'
import MenuItemContent from './MenuItemContent.vue'
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger
} from './tribo/ui/dropdown-menu'

defineProps<{
  sortType: 'time' | 'unread'
  showDarkModeSwitch: boolean
  massTextingEnabled: boolean
}>()

const emit = defineEmits<{
  sort: [type: 'time' | 'unread']
  createFolder: []
  massTexting: []
}>()

const toggleDarkMode = (event: Event) => {
  event.preventDefault()
  isDark.value = !isDark.value
}
</script>

<template>
  <header class="relative flex h-18 items-center justify-between px-4">
    <!-- Overlaid border, not a real `border-b` — see HeaderDivider.vue. -->
    <HeaderDivider />
    <DropdownMenu :modal="false">
      <DropdownMenuTrigger as-child>
        <button
          type="button"
          data-testid="conversation-menu-trigger"
          class="inline-flex h-10 cursor-pointer items-center gap-2 rounded-md px-2 text-xl font-bold text-content transition-colors hover:bg-surface-hover focus-visible:ring-1 focus-visible:ring-accent focus-visible:outline-none"
        >
          {{ $t('conversations') }}
          <ChevronDown class="h-4 w-4" aria-hidden="true" />
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuContent class="w-60" align="start">
        <DropdownMenuLabel class="text-xs font-normal text-content-muted">{{
          $t('sortOrder')
        }}</DropdownMenuLabel>
        <DropdownMenuRadioGroup
          :model-value="sortType"
          @update:model-value="emit('sort', $event as 'time' | 'unread')"
        >
          <DropdownMenuRadioItem
            value="time"
            indicator-position="end"
            data-testid="sort-time"
          >
            {{ $t('sortByTime') }}
            <template #indicator>
              <Check data-testid="sort-selected-indicator" class="h-4 w-4" />
            </template>
          </DropdownMenuRadioItem>
          <DropdownMenuRadioItem
            value="unread"
            indicator-position="end"
            data-testid="sort-unread"
          >
            {{ $t('sortByUnread') }}
            <template #indicator>
              <Check data-testid="sort-selected-indicator" class="h-4 w-4" />
            </template>
          </DropdownMenuRadioItem>
        </DropdownMenuRadioGroup>
        <template v-if="showDarkModeSwitch">
          <DropdownMenuSeparator />
          <DropdownMenuLabel class="text-xs font-normal text-content-muted">{{
            $t('appearance')
          }}</DropdownMenuLabel>
          <DropdownMenuCheckboxItem
            :checked="isDark"
            hide-indicator
            data-testid="dark-mode-switch"
            class="justify-between gap-3"
            @select="toggleDarkMode"
          >
            <span>{{ $t('darkMode') }}</span>
            <span
              aria-hidden="true"
              class="relative h-4 w-8 rounded-full border border-transparent transition-colors"
              :class="isDark ? 'bg-accent' : 'bg-border-strong'"
            >
              <span
                class="absolute top-px left-px h-3 w-3 rounded-full bg-surface transition-transform"
                :class="isDark ? 'translate-x-4' : 'translate-x-0'"
              />
            </span>
          </DropdownMenuCheckboxItem>
        </template>
      </DropdownMenuContent>
    </DropdownMenu>

    <DropdownMenu :modal="false">
      <DropdownMenuTrigger as-child>
        <button
          type="button"
          data-testid="create-menu-trigger"
          :aria-label="$t('create')"
          class="inline-flex h-10 w-10 cursor-pointer items-center justify-center rounded-md text-content transition-colors hover:bg-surface-hover focus-visible:ring-1 focus-visible:ring-accent focus-visible:outline-none"
        >
          <Plus class="h-5 w-5" aria-hidden="true" />
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuItem
          data-testid="create-folder-action"
          @select="emit('createFolder')"
        >
          <MenuItemContent :icon="FolderPlus" :label="$t('createFolder')" />
        </DropdownMenuItem>
        <DropdownMenuItem
          v-if="massTextingEnabled"
          data-testid="mass-texting-action"
          @select="emit('massTexting')"
        >
          <MenuItemContent :icon="Megaphone" :label="$t('createMassTexting')" />
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  </header>
</template>
