import { defineStore, type Pinia } from 'pinia'
import { actions } from './actions'
import { roomsInSelectedFolder } from './getters'
import type { ImkitState } from './state'
import { createState } from './state'

export const useImkitStore = defineStore('imkit', {
  state: createState,
  getters: {
    roomsInSelectedFolder: (state) => roomsInSelectedFolder(state as ImkitState)
  },
  actions
})

export type ImkitStore = ReturnType<typeof useImkitStore>

let imkitStore: ImkitStore | null = null

export const initImkitStore = (pinia?: Pinia): ImkitStore => {
  imkitStore = useImkitStore(pinia)
  return imkitStore
}

export const getImkitStore = (): ImkitStore => {
  if (imkitStore) return imkitStore
  return useImkitStore()
}

export const _resetImkitStoreForTests = (): void => {
  imkitStore = null
}

export type { ImkitState } from './state'
