<script setup lang="ts">
import {
  Folder as FolderIcon,
  MessageSquare,
  Plus,
  Search
} from 'lucide-vue-next'
import { computed, ref } from 'vue'
import { useVfm, VueFinalModal } from 'vue-final-modal'
import Folder from '../classes/folder'
import UpdateFolderModal from './folders/UpdateFolderModal.vue'
import { useImkitModal as useModal } from '../composables/useImkitModal'
import { useImkitStore } from '../stores/imkit'

// Sentinel for the 「未分類」 row — it is not a real folder id, just a local
// selection state meaning "remove from whichever folder the room is in".
const UNCLASSIFIED = '__unclassified__'

const vfm = useVfm()
const props = defineProps<{ roomId: string }>()
const imkit = useImkitStore()

const room = computed(() => imkit.rooms[props.roomId])

// A room lives in at most one folder client-side (see CLAUDE-facing store
// actions: addRoomToFolder/removeRoomFromFolder operate on a single
// folderId). There is no reverse index from roomId -> folderId, so find it
// by scanning the loaded folders.
const currentFolderId = computed(() => {
  for (const id of imkit.sortedFolderIds) {
    const folder = imkit.folders[id]
    if (folder && folder.roomIds.includes(props.roomId)) {
      return folder.id
    }
  }
  return ''
})

const searchKeyword = ref('')
const selectedFolderId = ref(currentFolderId.value || UNCLASSIFIED)

const sortedFolders = computed(() =>
  imkit.sortedFolderIds
    .map((id: string) => imkit.folders[id])
    .filter((folder: Folder) => folder)
)
const filteredFolders = computed(() => {
  const keyword = searchKeyword.value.trim().toLowerCase()
  if (!keyword) return sortedFolders.value
  return sortedFolders.value.filter((folder) =>
    folder.name.toLowerCase().includes(keyword)
  )
})

const hasChanged = computed(
  () => selectedFolderId.value !== (currentFolderId.value || UNCLASSIFIED)
)
const destinationName = computed(() => {
  if (selectedFolderId.value === UNCLASSIFIED) return ''
  return imkit.folders[selectedFolderId.value]?.name ?? ''
})

const select = (folderId: string) => {
  selectedFolderId.value = folderId
}

const submit = async () => {
  if (!props.roomId || !hasChanged.value) return
  try {
    const previousFolderId = currentFolderId.value
    if (previousFolderId) {
      await imkit.removeRoomFromFolder({
        roomId: props.roomId,
        folderId: previousFolderId
      })
    }
    if (selectedFolderId.value !== UNCLASSIFIED) {
      await imkit.addRoomToFolder({
        roomId: props.roomId,
        folderId: selectedFolderId.value
      })
    }
  } catch (error) {
    // Mirrors the pre-existing swallow-and-log here: both addRoomToFolder and
    // removeRoomFromFolder POST to /me/pref/<folderId> and throw on failure,
    // and the confirm handler closes the modal right after firing this
    // unawaited — an uncaught rejection would surface as unhandled with the
    // modal already gone. No toast infra in this SDK to surface it instead.
    console.error('Failed to move room between folders', error)
  }
}

const openCreateFolder = () => {
  vfm.closeAll()
  const { open } = useModal({
    component: UpdateFolderModal,
    attrs: { folderId: '' }
  })
  open()
}
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-surface rounded-lg border border-border p-5 flex flex-col gap-3 w-[360px] relative max-h-[80vh] overflow-y-auto shadow-raised"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div class="text-xl font-semibold text-content">
      {{ $t('addToFolder') }}
    </div>
    <p class="text-xs text-content-muted">
      {{
        $t('addToFolderExplain', {
          room: room?.displayName ?? '',
          folder: imkit.folders[currentFolderId]?.name ?? $t('unclassified')
        })
      }}
    </p>
    <div class="relative">
      <Search
        class="pointer-events-none absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-content-subtle"
      />
      <input
        v-model="searchKeyword"
        type="text"
        :aria-label="$t('searchFolder')"
        :placeholder="$t('searchFolder')"
        class="h-10 w-full rounded-md border border-border bg-surface py-2.5 pr-3.5 pl-9 text-base text-content placeholder-content-subtle outline-none focus:border-accent focus:ring-2 focus:ring-accent-subtle"
      />
    </div>
    <div class="flex flex-col overflow-hidden rounded-md border border-border">
      <button
        v-for="folder in filteredFolders"
        :key="folder.id"
        type="button"
        class="flex cursor-pointer items-center gap-3 border-b border-border p-2.5 text-left transition-colors last:border-b-0 hover:bg-surface-hover"
        @click="select(folder.id)"
      >
        <span
          class="flex h-4 w-4 shrink-0 items-center justify-center rounded-full border-2"
          :class="
            selectedFolderId === folder.id ? 'border-accent' : 'border-border'
          "
        >
          <span
            v-if="selectedFolderId === folder.id"
            class="h-2.5 w-2.5 rounded-full bg-accent"
          />
        </span>
        <span
          class="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-accent-subtle text-content-muted"
        >
          <FolderIcon :size="16" />
        </span>
        <span class="flex min-w-0 grow flex-col">
          <span class="truncate text-base text-content">{{ folder.name }}</span>
          <span class="text-xs text-content-muted">
            {{ $t('folderConversationCount', { n: folder.roomIds.length }) }}
          </span>
        </span>
        <!-- The 「目前」 badge also belongs on a REAL folder, not only on the
             Unclassified row. It was gated on `!currentFolderId`, so a room
             that actually lives in a folder got a pre-checked radio and no
             label saying which one it is currently in — the state the key
             exists to describe was unreachable. -->
        <span
          v-if="currentFolderId === folder.id"
          class="shrink-0 rounded-sm bg-accent-subtle px-2 py-0.5 text-xs font-medium text-accent-vivid"
        >
          {{ $t('currentLocation') }}
        </span>
      </button>
      <button
        type="button"
        class="flex cursor-pointer items-center gap-3 border-b border-border p-2.5 text-left transition-colors hover:bg-surface-hover"
        @click="select(UNCLASSIFIED)"
      >
        <span
          class="flex h-4 w-4 shrink-0 items-center justify-center rounded-full border-2"
          :class="
            selectedFolderId === UNCLASSIFIED
              ? 'border-accent'
              : 'border-border'
          "
        >
          <span
            v-if="selectedFolderId === UNCLASSIFIED"
            class="h-2.5 w-2.5 rounded-full bg-accent"
          />
        </span>
        <span
          class="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-surface-muted text-content-muted"
        >
          <MessageSquare :size="16" />
        </span>
        <span class="flex min-w-0 grow flex-col">
          <span class="truncate text-base text-content">{{
            $t('unclassified')
          }}</span>
          <span class="text-xs text-content-muted">{{
            $t('unclassifiedDescription')
          }}</span>
        </span>
        <span
          v-if="!currentFolderId"
          class="shrink-0 rounded-sm bg-accent-subtle px-2 py-0.5 text-xs font-medium text-accent-vivid"
        >
          {{ $t('currentLocation') }}
        </span>
      </button>
      <button
        type="button"
        class="flex cursor-pointer items-center gap-2 p-2.5 text-left text-accent-vivid transition-colors hover:bg-surface-hover"
        @click="openCreateFolder"
      >
        <Plus :size="16" />
        <span class="text-base font-medium">{{
          $t('createNewFolderPrompt')
        }}</span>
      </button>
    </div>
    <div class="mt-1 flex items-center justify-end gap-2">
      <button
        class="inline-flex h-10 cursor-pointer items-center justify-center rounded-md bg-surface-muted px-4 text-base font-medium text-content transition-colors"
        @click="vfm.closeAll()"
      >
        {{ $t('cancel') }}
      </button>
      <button
        class="inline-flex h-10 items-center justify-center rounded-md bg-accent px-4 text-base font-medium text-white transition-colors disabled:cursor-not-allowed disabled:bg-surface-muted disabled:text-content-faint"
        :disabled="!hasChanged"
        @click="
          () => {
            submit()
            vfm.closeAll()
          }
        "
      >
        {{
          selectedFolderId === UNCLASSIFIED
            ? $t('removeFromFolder')
            : $t('moveToFolder', { name: destinationName })
        }}
      </button>
    </div>
  </vue-final-modal>
</template>
