<script setup lang="ts">
/**
 * Shared send-button definition (round 12, item 8) — the composer's mobile
 * send control and the voice-recorder's send control used to be two
 * separate icon components (`lucide-vue-next`'s `Send`, a raw SVG) styled
 * to merely look alike. That is exactly the kind of divergence
 * `MenuItemContent` was extracted to stop: two call sites that are SUPPOSED
 * to be identical but are defined twice drift the moment only one of them
 * gets touched. This component is now the single definition both use; only
 * layout (margins) stays at the call site, via the normal `class` fallthrough.
 */
import SendSvg from './svgs/SendSvg.vue'

defineProps<{ enabled: boolean }>()
const emit = defineEmits<{ click: [] }>()
</script>

<template>
  <SendSvg
    data-testid="send-button"
    class="h-6 w-6 shrink-0"
    :class="
      enabled
        ? 'cursor-pointer fill-accent-vivid'
        : 'cursor-not-allowed fill-content-faint'
    "
    @mousedown.prevent
    @click="enabled && emit('click')"
  />
</template>
