<script setup lang="ts">
import { X } from 'lucide-vue-next'
import { RecordRTCPromisesHandler } from 'recordrtc'
import { v4 as uuidv4 } from 'uuid'
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import Styles from '../classes/styles'
import { getConfig } from '../runtime/config'
import { useImkitStore } from '../stores/imkit'
import MessageSendButton from './MessageSendButton.vue'

enum AudioRecordState {
  WillRecord,
  DidRecord,
  WillStop,
  DidStop
}
const { t } = useI18n()
const imkit = useImkitStore()
const config = getConfig()
const styles = computed((): Styles => config.styles)
const audioRecordState = ref(AudioRecordState.DidStop)
const stream = ref<MediaStream>()
const recorder = ref<RecordRTCPromisesHandler>()
const audioContext = ref<AudioContext>()
const source = ref<MediaStreamAudioSourceNode>()
const mimeType = 'audio/webm'
const maxDuration = 180
const duration = ref(0)
const timestamp = ref(0)
const durationIntervalId = ref<number>()
const volumeIntervalId = ref<number>()
const volumes = reactive<number[]>([])
const errorMessage = ref('')
// handleAudioRecord auto-starts on mount and awaits getUserMedia (the mic
// permission prompt, seconds long) and startRecording. If the component unmounts
// during either await, onUnmounted's cleanup() no-ops because no handles exist
// yet, then the resolved continuation would acquire the mic / AudioContext /
// timers on a dead component. This flag lets the continuation bail and tear down.
let isUnmounted = false
const canSend = computed(() => {
  return duration.value > 1
})
// Release every recording resource (timers, mic tracks, audio graph, context).
// Called from the normal stop branch, the start-failure catch, and onUnmounted,
// so a new AudioContext is never leaked (browsers cap ~6) and the mic never
// stays live. Safe to call repeatedly — all handles are optional and nulled.
const cleanup = () => {
  clearInterval(durationIntervalId.value)
  clearInterval(volumeIntervalId.value)
  durationIntervalId.value = undefined
  volumeIntervalId.value = undefined
  stream.value?.getTracks().forEach((track) => track.stop())
  stream.value = undefined
  source.value?.disconnect()
  source.value = undefined
  if (audioContext.value && audioContext.value.state !== 'closed') {
    audioContext.value.close().catch(() => {})
  }
  audioContext.value = undefined
}
const handleAudioRecord = async () => {
  try {
    switch (audioRecordState.value) {
      case AudioRecordState.DidStop: {
        audioRecordState.value = AudioRecordState.WillRecord
        errorMessage.value = ''
        volumes.splice(0)
        duration.value = 0
        timestamp.value = 0
        stream.value = await navigator.mediaDevices.getUserMedia({
          video: false,
          audio: true
        })
        if (isUnmounted) {
          cleanup()
          return
        }
        recorder.value = new RecordRTCPromisesHandler(stream.value, {
          type: 'audio',
          mimeType
        })
        const ctx = new AudioContext()
        audioContext.value = ctx
        const analyser = ctx.createAnalyser()
        analyser.fftSize = 64
        analyser.smoothingTimeConstant = 0.0
        source.value = ctx.createMediaStreamSource(stream.value)
        source.value.connect(analyser)
        volumeIntervalId.value = window.setInterval(() => {
          let dataArray = new Uint8Array(analyser.frequencyBinCount)
          analyser.getByteFrequencyData(dataArray)
          let average = dataArray.reduce((a, b) => a + b) / dataArray.length
          const value = Math.min(1, average / 128)
          volumes.unshift(value)
        }, 100)
        await recorder.value.startRecording()
        if (isUnmounted) {
          cleanup()
          return
        }
        timestamp.value = Date.now()
        durationIntervalId.value = window.setInterval(() => {
          duration.value = (Date.now() - timestamp.value) / 1000
          if (duration.value >= maxDuration) {
            handleAudioRecord()
          }
        }, 1000)
        audioRecordState.value = AudioRecordState.DidRecord
        break
      }
      case AudioRecordState.DidRecord:
        audioRecordState.value = AudioRecordState.WillStop
        await recorder.value?.stopRecording()
        cleanup()
        audioRecordState.value = AudioRecordState.DidStop
        break
      default:
        break
    }
  } catch (error) {
    console.error(error)
    errorMessage.value = t('noAccessMicrophonePermission')
    // a throw mid-start (e.g. startRecording) leaves the mic/context/timers
    // live and the state stuck at WillRecord (dead button) — release and reset.
    cleanup()
    audioRecordState.value = AudioRecordState.DidStop
  }
}
const send = async () => {
  if (audioRecordState.value !== AudioRecordState.DidStop) {
    await handleAudioRecord()
  }
  const recordedDuration = timestamp.value
    ? (Date.now() - timestamp.value) / 1000
    : duration.value
  volumes.splice(0)
  duration.value = 0
  timestamp.value = 0
  let blob = await recorder.value?.getBlob()
  if (blob) {
    const file = new File([blob], `${uuidv4()}.webm`)
    const payload = {
      roomId: imkit.selectedRoomId,
      messageType: 'audio',
      file,
      duration: recordedDuration,
      originalUrl: '',
      extra: {
        mimeType,
        fileName: file.name.split('.').slice(0, -1).join('.'),
        bytes: file.size,
        fileExtension: file.name.split('.').pop()
      }
    }
    await imkit.sendMessage(payload)
  }
}
onMounted(() => {
  handleAudioRecord()
})
onUnmounted(() => {
  isUnmounted = true
  cleanup()
})
</script>

<template>
  <div class="flex grow items-center gap-1">
    <div
      class="relative flex h-11 w-0 min-w-0 grow items-center gap-3 rounded-xl bg-surface-muted px-3"
    >
      <div
        data-testid="audio-record-button"
        class="flex h-8 w-8 shrink-0 items-center justify-center rounded-full border border-border"
        @click="handleAudioRecord"
      >
        <div
          class="h-6 w-6 rounded-full bg-danger transition-all duration-200 ease-in"
          :class="{
            'h-3! w-3! rounded-sm':
              audioRecordState == AudioRecordState.DidRecord,
            'cursor-not-allowed bg-danger/50': errorMessage
          }"
        />
      </div>
      <Transition>
        <div
          v-if="errorMessage"
          class="flex items-center gap-1 rounded-lg bg-surface p-2 text-xs text-content-muted transition duration-150 ease-in-out"
        >
          <X :size="16" class="h-4 w-4 text-content-muted" />
          {{ errorMessage }}
        </div>
      </Transition>
      <div class="volumes">
        <div
          v-for="(volume, index) in volumes"
          :key="index"
          class="min-h-0.5! w-0.5 shrink-0 rounded-sm bg-content-faint"
          :style="{ height: `${volume * 28}px` }"
        />
      </div>
      <div
        class="ml-auto rounded-full bg-accent px-2 py-1 text-xs font-bold text-white"
      >
        {{ Math.floor(duration / 60) }}:{{
          `${Math.floor(duration % 60)}`.padStart(2, '0')
        }}
      </div>
    </div>
    <!-- Round 12: shares its definition with the composer's mobile send
         button via MessageSendButton.vue — see that component's doc
         comment. -->
    <MessageSendButton
      :enabled="canSend"
      class="mr-1 ml-2"
      :style="canSend ? styles.sendButtonEnabled : styles.sendButtonDisabled"
      @click="send"
    />
  </div>
</template>

<style scoped>
@reference 'tailwindcss';
.volumes {
  @apply flex h-full flex-row-reverse items-center gap-0.5 overflow-auto;
  -ms-overflow-style: none; /* IE and Edge */
  scrollbar-width: none; /* Firefox */
}
.volumes::-webkit-scrollbar {
  display: none;
}
</style>
