import IMImage from '../classes/image'

/**
 * Calculate display dimensions for an image in a grid layout.
 * Maintains aspect ratio for single images, uses fixed size for grids.
 */
export const calculateImageSize = (
  index: number,
  image: IMImage,
  totalImages: number
): { width: string; height: string } => {
  const size = 200
  const { width, height } = image

  // Fallback to default size if dimensions are missing or invalid
  if (!width || !height || width <= 0 || height <= 0) {
    if (totalImages > 1) {
      if (index === totalImages - 1 && index % 2 === 0) {
        return { width: `${size * 2 + 1}px`, height: `${size}px` }
      }
      return { width: `${size}px`, height: `${size}px` }
    }
    return { width: `${size}px`, height: `${size}px` }
  }

  if (totalImages === 1) {
    if (width < height) {
      return {
        width: `${size}px`,
        height: `${(size * height) / width}px`
      }
    } else {
      return {
        width: `${(size * width) / height}px`,
        height: `${size}px`
      }
    }
  } else {
    if (index === totalImages - 1 && index % 2 === 0) {
      return { width: `${size * 2 + 1}px`, height: `${size}px` }
    }
    return { width: `${size}px`, height: `${size}px` }
  }
}
