<script setup lang="ts">
import { ref } from 'vue'
import { useVfm } from 'vue-final-modal'
import { useImkitStore } from '../stores/imkit'
import ConfirmDialogShell from './ConfirmDialogShell.vue'

const props = defineProps<{ roomId: string; memberId: string }>()

const vfm = useVfm()
const imkit = useImkitStore()
const showError = ref(false)
const isLoading = ref(false)

const cancelLeave = () => {
  vfm.closeAll()
}

const executeLeave = async () => {
  isLoading.value = true
  try {
    await imkit.removeMembers({
      roomId: props.roomId,
      uids: [props.memberId]
    })
    vfm.closeAll()
  } catch (error) {
    console.error('Failed to leave group:', error)
    showError.value = true
  } finally {
    isLoading.value = false
  }
}

const closeError = () => {
  showError.value = false
  vfm.closeAll()
}

// Single root, see BlockUserConfirmModal.vue's comment: two ConfirmDialogShell
// roots toggled by v-if/v-else would break attrs fallthrough.
const onConfirm = () => (showError.value ? closeError() : executeLeave())
</script>

<template>
  <ConfirmDialogShell
    :title="
      showError ? $t('leaveGroupErrorTitle') : $t('leaveGroupConfirmTitle')
    "
    :cancel-label="showError ? undefined : $t('cancel')"
    :confirm-label="showError ? $t('confirm') : $t('leaveGroupConfirmAction')"
    :loading="!showError && isLoading"
    @cancel="cancelLeave"
    @confirm="onConfirm"
  >
    {{ showError ? $t('leaveGroupErrorDesc') : $t('leaveGroupConfirmTip') }}
  </ConfirmDialogShell>
</template>
