// Window for coalescing a reconnect-resync burst. Spans the socket's
// reconnectionDelayMax (5s) so the >60s visibility return's direct call and the
// socket 'connect' follow-up collapse into one refresh; a genuinely later
// reconnect still resyncs.
const RECONNECT_RESYNC_COOLDOWN_MS = 5000
// Keep each room in its own pref: clients editing different rooms must not
// replace one another's drafts with a stale whole-map snapshot.
const MESSAGE_DRAFT_PREF_PREFIX = 'messageDraft:'
const MESSAGE_DRAFT_DEBOUNCE_MS = 500
const messageDraftPrefKey = (roomId: string) =>
  `${MESSAGE_DRAFT_PREF_PREFIX}${encodeURIComponent(roomId)}`
const messageDraftStoragePrefix = () => {
  const uid = getUid()
  return uid ? `imkit:messageDraft:${uid}:` : ''
}
type LocalDraftChanges = Record<string, string | null>
const readLocalDraftChanges = (): LocalDraftChanges => {
  const prefix = messageDraftStoragePrefix()
  if (!prefix || typeof localStorage === 'undefined') return {}
  const changes: LocalDraftChanges = {}
  try {
    for (let index = 0; index < localStorage.length; index++) {
      const key = localStorage.key(index)
      if (!key?.startsWith(prefix)) continue
      try {
        const roomId = decodeURIComponent(key.slice(prefix.length))
        const value: unknown = JSON.parse(localStorage.getItem(key) || 'null')
        if (value === null || typeof value === 'string') changes[roomId] = value
      } catch (error) {
        console.error('Failed to read local message draft', error)
      }
    }
    return changes
  } catch (error) {
    console.error('Failed to read local message drafts', error)
    return changes
  }
}
const writeLocalDraftChange = (roomId: string, text: string | null) => {
  const prefix = messageDraftStoragePrefix()
  if (!prefix || typeof localStorage === 'undefined') return
  try {
    localStorage.setItem(
      `${prefix}${encodeURIComponent(roomId)}`,
      JSON.stringify(text)
    )
  } catch (error) {
    console.error('Failed to cache message drafts locally', error)
  }
}
const clearLocalDraftChange = (roomId: string, expected: string | null) => {
  const prefix = messageDraftStoragePrefix()
  if (!prefix || typeof localStorage === 'undefined') return
  const key = `${prefix}${encodeURIComponent(roomId)}`
  try {
    if (JSON.parse(localStorage.getItem(key) || 'null') === expected) {
      localStorage.removeItem(key)
    }
  } catch (error) {
    console.error('Failed to clear local message draft', error)
  }
}
const draftWrites = new WeakMap<
  object,
  {
    timer: ReturnType<typeof setTimeout> | null
    queue: Promise<void>
    dirty: Set<string>
  }
>()

function draftWriteState(store: object) {
  let state = draftWrites.get(store)
  if (!state) {
    state = { timer: null, queue: Promise.resolve(), dirty: new Set() }
    draftWrites.set(store, state)
  }
  return state
}

// Trailing-throttle window for the room-list re-sort. A burst of inbound socket
// events (e.g. a post-reconnect replay of dozens of missed messages, or a
// broadcast) would otherwise run aggregateRoomsAndFolders — an O(n log n) re-sort
// over every cached room — once PER event. Coalescing to one re-sort per window
// keeps the list responsive; ~2 frames of staleness is imperceptible.
const AGGREGATE_COALESCE_MS = 32
const ROOM_CONTENT_PAGE_SIZE = 20
const ROOM_CONTENT_FILE_TYPES = {
  Preview: 'image,video,audio,document',
  Media: 'image,video',
  Files: 'audio,document'
} as const

type RoomContentCollection = keyof typeof ROOM_CONTENT_FILE_TYPES

const roomContentPageRequests = new WeakMap<
  object,
  Map<string, Promise<void>>
>()

const seedRoomContentSignedUrls = (items: ChatRoomContent[]) => {
  for (const item of items) {
    if (!item?.room) continue

    const entries = [
      { fileId: item._id, signedUrl: item.signedUrl },
      {
        fileId: item.preview?._id,
        signedUrl: item.preview?.signedUrl
      }
    ]
    for (const { fileId, signedUrl } of entries) {
      if (!fileId || typeof signedUrl !== 'string' || !signedUrl) continue
      const canonicalPath = `/files/${item.room}/${fileId}`
      if (!getSignedUrl(canonicalPath)) {
        setSignedUrl(canonicalPath, signedUrl)
      }
    }
  }
}

function fetchRoomContentPage(
  store: any,
  collection: RoomContentCollection,
  { roomId, loadMore = false }: { roomId: string; loadMore?: boolean }
): Promise<void> {
  let storeRequests = roomContentPageRequests.get(store)
  if (!storeRequests) {
    storeRequests = new Map()
    roomContentPageRequests.set(store, storeRequests)
  }
  const requestKey = `${store.sessionEpoch}:${collection}:${roomId}:${loadMore ? 'more' : 'initial'}`
  const existingRequest = storeRequests.get(requestKey)
  if (existingRequest) return existingRequest

  const request = runFetchRoomContentPage(store, collection, {
    roomId,
    loadMore
  }).finally(() => {
    if (storeRequests?.get(requestKey) === request) {
      storeRequests.delete(requestKey)
    }
  })
  storeRequests.set(requestKey, request)
  return request
}

async function runFetchRoomContentPage(
  store: any,
  collection: RoomContentCollection,
  { roomId, loadMore = false }: { roomId: string; loadMore?: boolean }
): Promise<void> {
  const stateKey = `chatRoomContent${collection}`
  const roomIdKey = `${stateKey}RoomId`
  const loadingKey = `${stateKey}Loading`
  const loadingMoreKey = `${stateKey}LoadingMore`
  const offsetKey = `${stateKey}Offset`
  const totalCountKey = `${stateKey}TotalCount`
  const hasMoreKey = `${stateKey}HasMore`
  const requestSessionEpoch = store.sessionEpoch

  if (loadMore && store[roomIdKey] !== roomId) return

  const offset = loadMore ? store[offsetKey] : 0
  if (loadMore) {
    store[loadingMoreKey] = true
  } else {
    store.$patch({
      [stateKey]: [],
      [roomIdKey]: roomId,
      [loadingKey]: true,
      [offsetKey]: 0,
      [totalCountKey]: 0,
      [hasMoreKey]: true
    })
  }

  try {
    const { data } = await getAxios().get(
      `/files/room/${roomId}?fileTypes=${ROOM_CONTENT_FILE_TYPES[collection]}&limit=${ROOM_CONTENT_PAGE_SIZE}&offset=${offset}&orderBy=message${collection === 'Files' ? '' : '&sortOrder=desc'}`
    )
    if (
      store.sessionEpoch !== requestSessionEpoch ||
      store[roomIdKey] !== roomId
    ) {
      return
    }

    const newData = Array.isArray(data.result?.data) ? data.result.data : []
    seedRoomContentSignedUrls(newData)
    const totalCount = Number(data.result?.totalCount) || 0
    const newOffset = offset + newData.length
    const existingItems = loadMore ? store[stateKey] : []
    const existingIds = new Set(
      existingItems.map((item: ChatRoomContent) => item._id)
    )
    const uniqueNewData = newData.filter(
      (item: ChatRoomContent) => !existingIds.has(item._id)
    )
    store.$patch({
      [stateKey]: loadMore
        ? [...existingItems, ...uniqueNewData]
        : uniqueNewData,
      [offsetKey]: newOffset,
      [totalCountKey]: totalCount,
      [hasMoreKey]: newOffset < totalCount,
      [loadingKey]: false,
      [loadingMoreKey]: false
    })
  } catch (error) {
    if (
      store.sessionEpoch === requestSessionEpoch &&
      store[roomIdKey] === roomId
    ) {
      store.$patch({
        [roomIdKey]: loadMore ? roomId : '',
        [loadingKey]: false,
        [loadingMoreKey]: false
      })
    }
    throw error
  }
}

const mergeUsersIntoStore = (store: any, users: Record<string, User>) => {
  for (const id in users) {
    const existing = store.users[id]
    if (existing) {
      const incoming = users[id] as any
      for (const prop in incoming) {
        // A user can arrive sparse — e.g. only as a nested group member, whose
        // payload carries just `_id`. The User ctor then fills the absent fields
        // with placeholders: avatarUrl/country/city/clientType => null/undefined,
        // nickname => the raw id, memberIds => {}. Treat every placeholder as "no
        // value" so a sparse record never downgrades an already-loaded fuller
        // one; a genuinely meaningful incoming value still wins.
        const value = incoming[prop]
        const isPlaceholder =
          value == null ||
          (prop === 'nickname' && value === incoming.id) ||
          (prop === 'memberIds' && Object.keys(value).length === 0)
        if (!isPlaceholder || existing[prop] == null) {
          existing[prop] = value
        }
      }
    } else {
      store.users[id] = users[id]
    }
  }
}

const mergeInto = (store: any, key: string, value: Record<string, unknown>) => {
  Object.assign(store[key], value)
}

// Shared media-upload payload rewriting for sendMessage/retryMessage. Both
// sites turn local image/mixed and file/audio payloads (carrying File handles
// and local data:/blob: urls) into server payloads (carrying uploaded urls).
// The mechanics are byte-identical across the two sites; only the *guards* and
// the video path differ, so those stay inline at each call site. `localId` is
// the id used for single-file uploads + progress (deliveringMessage.id on send,
// localMessage.id on retry).
const resolveMediaPayload = async (
  store: any,
  payload: Record<string, any>,
  roomId: string,
  localId: string
): Promise<void> => {
  if (
    payload.messageType === MessageType.Image ||
    payload.messageType === MessageType.Mixed
  ) {
    const files = payload.files as File[]
    const sourceImages = payload.images as IMImage[]
    const urls = await Promise.all(
      sourceImages.map((image, index) =>
        store.uploadImage({
          image,
          file: files[index],
          roomId
        })
      )
    )
    const uploadedImages: {
      originalUrl: string
      thumbnailUrl: string
      width: number
      height: number
    }[] = []
    sourceImages.forEach((image, index) => {
      imageCache.set(urls[index].thumbnailUrl, image.thumbnailUrl)
      const { id, width, height } = image
      uploadedImages.push({
        originalUrl: urls[index].originalUrl,
        thumbnailUrl: urls[index].thumbnailUrl,
        width,
        height
      })
      store.uploadProgresses[`${id}-original`] = 1
      store.uploadProgresses[`${id}-thumbnail`] = 1
    })
    payload.images = uploadedImages
    delete payload.files
  } else if (
    payload.messageType === MessageType.File ||
    payload.messageType === MessageType.Audio
  ) {
    const url = await store.uploadMedia({
      id: localId,
      file: payload.file,
      roomId
    })
    payload.originalUrl = url
    delete payload.file
    store.uploadProgresses[localId] = 1
  }
}

const MAX_CACHED_ROOMS = 20

const evictOldRoomCaches = (state: any) => {
  if (state.messageMultiLists.size <= MAX_CACHED_ROOMS) return
  for (const roomId of state.messageMultiLists.keys()) {
    if (roomId === state.selectedRoomId) continue
    state.messageMultiLists.delete(roomId)
    state.numberOfTotalMessages.delete(roomId)
    state.searchedMessageIds.delete(roomId)
    if (state.messageMultiLists.size <= MAX_CACHED_ROOMS) break
  }
}

async function markRoomLastRead(store: any, roomId: string) {
  const path = `/rooms/${roomId}/lastRead`
  if (store.isRequesting[path]) return
  const room = store.rooms[roomId]
  if (!room) return
  const {
    data: { result }
  } = await getAxios().put(path, {
    message: room.lastMessage?.id
  })
  if (result) {
    store.updateRoom({
      id: roomId,
      numberOfUnread: 0,
      isMentioned: false
    } as Room)
  }
}

