import {
  palette,
  type DesignPalette,
  type PaletteSeeds
} from '../classes/styles'

type Rgb = [number, number, number]

type Oklch = {
  L: number
  C: number
  h: number
}

export const DESIGN_TOKEN_NAMES = [
  'surface',
  'panel',
  'canvas',
  'surface-muted',
  'surface-hover',
  'surface-sunken',
  'field',
  'border',
  'border-strong',
  'content',
  'content-subtle',
  'content-muted',
  'content-faint',
  'accent',
  'accent-vivid',
  'accent-hover',
  'accent-subtle',
  'danger',
  'danger-vivid',
  'message',
  'message-border',
  'message-own',
  'message-own-content',
  'highlight',
  'highlight-content',
  'tooltip'
] as const

export type DesignTokenName = (typeof DESIGN_TOKEN_NAMES)[number]
export type DesignTokens = Record<DesignTokenName, string>

const clamp = (value: number, min: number, max: number): number =>
  Math.min(max, Math.max(min, value))

const toLinear = (value: number): number =>
  value <= 0.04045 ? value / 12.92 : Math.pow((value + 0.055) / 1.055, 2.4)

const fromLinear = (value: number): number =>
  value <= 0.0031308 ? value * 12.92 : 1.055 * Math.pow(value, 1 / 2.4) - 0.055

function hexToRgb(hex: string): Rgb {
  let value = String(hex || '')
    .replace('#', '')
    .trim()
  if (value.length === 3) {
    value = value
      .split('')
      .map((character) => character + character)
      .join('')
  }
  if (value.length !== 6 || /[^0-9a-f]/i.test(value)) {
    return [0.5, 0.5, 0.5]
  }
  return [0, 2, 4].map(
    (index) => parseInt(value.slice(index, index + 2), 16) / 255
  ) as Rgb
}

function rgbToHex(rgb: Rgb): string {
  return `#${rgb
    .map((channel) =>
      Math.round(clamp(channel, 0, 1) * 255)
        .toString(16)
        .padStart(2, '0')
    )
    .join('')}`
}

function normaliseHex(value: string): string {
  return rgbToHex(hexToRgb(value))
}

function rgbToOklch(rgb: Rgb): Oklch {
  const [red, green, blue] = rgb.map(toLinear) as Rgb
  const l = Math.cbrt(
    0.4122214708 * red + 0.5363325363 * green + 0.0514459929 * blue
  )
  const m = Math.cbrt(
    0.2119034982 * red + 0.6806995451 * green + 0.1073969566 * blue
  )
  const s = Math.cbrt(
    0.0883024619 * red + 0.2817188376 * green + 0.6299787005 * blue
  )
  const L = 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s
  const a = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s
  const b = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s
  let h = (Math.atan2(b, a) * 180) / Math.PI
  if (h < 0) h += 360
  return { L, C: Math.sqrt(a * a + b * b), h }
}

function oklchToRgb(L: number, C: number, h: number): Rgb {
  const radians = (h * Math.PI) / 180
  const a = Math.cos(radians) * C
  const b = Math.sin(radians) * C
  const l_ = L + 0.3963377774 * a + 0.2158037573 * b
  const m_ = L - 0.1055613458 * a - 0.0638541728 * b
  const s_ = L - 0.0894841775 * a - 1.291485548 * b
  const l = l_ * l_ * l_
  const m = m_ * m_ * m_
  const s = s_ * s_ * s_
  return [
    fromLinear(4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s),
    fromLinear(-1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s),
    fromLinear(-0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s)
  ]
}

function oklchToHex(L: number, C: number, h: number): string {
  let chroma = Math.max(0, C)
  const lightness = clamp(L, 0, 1)
  for (let iteration = 0; iteration < 30; iteration += 1) {
    const rgb = oklchToRgb(lightness, chroma, h)
    if (rgb.every((channel) => channel >= -0.004 && channel <= 1.004)) break
    chroma *= 0.9
  }
  return rgbToHex(oklchToRgb(lightness, chroma, h))
}

export function relativeLuminance(hex: string): number {
  const [red, green, blue] = hexToRgb(hex).map(toLinear) as Rgb
  return 0.2126 * red + 0.7152 * green + 0.0722 * blue
}

export function contrastRatio(foreground: string, background: string): number {
  const foregroundLuminance = relativeLuminance(foreground)
  const backgroundLuminance = relativeLuminance(background)
  return (
    (Math.max(foregroundLuminance, backgroundLuminance) + 0.05) /
    (Math.min(foregroundLuminance, backgroundLuminance) + 0.05)
  )
}

function ensureContrast(
  foreground: string,
  background: string,
  minimum: number
): string {
  const colour = rgbToOklch(hexToRgb(foreground))
  const darken = relativeLuminance(background) > 0.2
  let lightness = colour.L
  let result = oklchToHex(lightness, colour.C, colour.h)
  for (
    let iteration = 0;
    iteration < 200 && contrastRatio(result, background) < minimum;
    iteration += 1
  ) {
    lightness += darken ? -0.004 : 0.004
    if (lightness <= 0 || lightness >= 1) break
    result = oklchToHex(lightness, colour.C, colour.h)
  }
  if (contrastRatio(result, background) < minimum) {
    const blackRatio = contrastRatio('#000000', background)
    const whiteRatio = contrastRatio('#ffffff', background)
    result = blackRatio >= whiteRatio ? '#000000' : '#ffffff'
  }
  return result
}

type ContrastConstraint = {
  background: string
  minimum: number
}

function ensureContrastAcross(
  foreground: string,
  constraints: ContrastConstraint[]
): string {
  const colour = rgbToOklch(hexToRgb(foreground))
  const satisfies = (candidate: string): boolean =>
    constraints.every(
      ({ background, minimum }) =>
        contrastRatio(candidate, background) >= minimum
    )
  const initial = oklchToHex(colour.L, colour.C, colour.h)
  if (satisfies(initial)) return initial

  for (let step = 1; step <= 500; step += 1) {
    const distance = step * 0.002
    for (const lightness of [colour.L - distance, colour.L + distance]) {
      if (lightness < 0 || lightness > 1) continue
      const candidate = oklchToHex(lightness, colour.C, colour.h)
      if (satisfies(candidate)) return candidate
    }
  }

  for (const candidate of ['#000000', '#ffffff']) {
    if (satisfies(candidate)) return candidate
  }

  throw new Error(
    `Unable to derive a colour that satisfies ${constraints.length} contrast constraints`
  )
}

function bestForeground(background: string): string {
  return contrastRatio('#ffffff', background) >=
    contrastRatio('#0d0d0d', background)
    ? '#ffffff'
    : oklchToHex(0.2, 0.02, rgbToOklch(hexToRgb(background)).h)
}

function toRgba(hex: string, alpha: number): string {
  const [red, green, blue] = hexToRgb(hex).map((channel) =>
    Math.round(channel * 255)
  )
  return `rgba(${red}, ${green}, ${blue}, ${alpha})`
}

function compositeHex(foreground: string, background: string, alpha: number) {
  const foregroundRgb = hexToRgb(foreground)
  const backgroundRgb = hexToRgb(background)
  return rgbToHex(
    foregroundRgb.map(
      (channel, index) => channel * alpha + backgroundRgb[index] * (1 - alpha)
    ) as Rgb
  )
}

/** Derives the complete semantic colour-token set from six seed colours. */
export function deriveTokens(seeds: PaletteSeeds, dark: boolean): DesignTokens {
  const safeSeeds: PaletteSeeds = {
    brand: normaliseHex(seeds.brand),
    neutral: normaliseHex(seeds.neutral),
    text: normaliseHex(seeds.text),
    ownBubble: normaliseHex(seeds.ownBubble),
    danger: normaliseHex(seeds.danger),
    highlight: normaliseHex(seeds.highlight)
  }
  const neutral = rgbToOklch(hexToRgb(safeSeeds.neutral))
  const brand = rgbToOklch(hexToRgb(safeSeeds.brand))
  const text = rgbToOklch(hexToRgb(safeSeeds.text))
  const ownBubble = rgbToOklch(hexToRgb(safeSeeds.ownBubble))
  const highlight = rgbToOklch(hexToRgb(safeSeeds.highlight))
  const neutralChroma = Math.min(neutral.C, 0.045)

  if (!dark) {
    const surface = oklchToHex(1, neutralChroma * 0.12, neutral.h)
    const panel = surface
    const canvas = oklchToHex(0.986, neutralChroma * 0.45, neutral.h)
    const surfaceMuted = oklchToHex(0.982, neutralChroma * 0.4, neutral.h)
    // The hover fill, split out of `surface-muted` on 2026-08-17. The two
    // shared one value, so the only way to deepen a hover was to deepen ~81
    // cards, chips and spinner tracks with it. Every hover surface — room
    // rows, dropdown-menu items, the round icon buttons — points here now,
    // which is also what keeps menus and the room list matching each other.
    //
    // 0.972 rather than `surface-muted`'s 0.982: at 1.050 against the panel
    // the old fill was reported as too faint, and `accent-subtle` (1.13) had
    // already been rejected as too deep, so the usable window is narrow.
    // 0.978. Note this is now LIGHTER than `field` (0.976), and the two are
    // effectively the same colour to the eye: at their widest possible
    // separation in this range they measure 1.018 against each other, far
    // under any perceptibility threshold. The light palette from `panel`
    // (#feffff) down to "too deep" spans only about 1.05-1.09 in contrast,
    // and both tokens live inside that band, so their ORDER is adjustable
    // but their DISTINCTNESS is not. If these two ever need to be told apart,
    // it has to come from another channel — a border, a radius, elevation —
    // not from moving either value.
    const surfaceHover = oklchToHex(0.978, neutralChroma * 0.4, neutral.h)
    const surfaceSunken = oklchToHex(0.965, neutralChroma * 0.6, neutral.h)
    // The fill shared by the three input fields (composer, room-list search,
    // in-room search). Its own token rather than `surface-muted`, which it
    // used to borrow: that token also backs 34 hover states and ~78 cards and
    // chips, so there was no way to deepen the fields without dragging all of
    // those with them.
    //
    // How deep this can go is set by the PLACEHOLDER, not by taste.
    // Placeholders are `content-subtle` and must clear 4.5:1 (see the
    // placeholder note in style.css), and the margin is thin: at L 0.95 the
    // placeholder measures 4.45:1 and is already under the floor. The usable
    // range between `surface-muted`'s 0.982 and that wall is roughly one
    // step, and 0.97 sits inside it at 4.70:1.
    // 0.976, and NOT 0.973 — `surface-hover` sits at 0.972, so that step
    // derives the identical hex (#eff7ff) and the room-list search field
    // would merge into the hover fill of the row directly beneath it. The
    // two tokens are neighbours on this scale now; keep a step between them
    // whenever either moves.
    const field = oklchToHex(0.976, neutralChroma * 0.5, neutral.h)
    const border = oklchToHex(0.932, neutralChroma * 0.85, neutral.h)
    const accentSubtle = oklchToHex(0.955, Math.min(brand.C, 0.035), brand.h)
    const accent = ensureContrastAcross(safeSeeds.brand, [
      { background: '#ffffff', minimum: 4.5 },
      { background: surface, minimum: 3 },
      { background: panel, minimum: 3 }
    ])
    const messageOwn =
      ownBubble.L >= 0.78
        ? safeSeeds.ownBubble
        : oklchToHex(0.78, ownBubble.C, ownBubble.h)
    const accentVivid = ensureContrastAcross(safeSeeds.brand, [
      ...[surface, panel, canvas, surfaceMuted, accentSubtle].map(
        (background) => ({ background, minimum: 4.5 })
      ),
      { background: messageOwn, minimum: 3 }
    ])
    const borderStrong = ensureContrastAcross(
      oklchToHex(0.61, Math.min(neutralChroma, 0.014), neutral.h),
      [surface, panel, canvas, surfaceMuted, border].map((background) => ({
        background,
        minimum: 3
      }))
    )
    return {
      surface,
      panel,
      canvas,
      'surface-muted': surfaceMuted,
      'surface-hover': surfaceHover,
      'surface-sunken': surfaceSunken,
      field,
      border,
      'border-strong': borderStrong,
      content: ensureContrast(safeSeeds.text, surface, 12),
      'content-subtle': ensureContrastAcross(
        oklchToHex(0.55, Math.min(neutralChroma, 0.03), neutral.h),
        // `field` is in this list because `content-subtle` is the placeholder
        // colour. Without it the placeholder's 4.5:1 on the field fill would
        // only hold for the default seeds and could quietly break for a
        // customer's `neutral`; here the derivation corrects for it instead.
        [surface, canvas, surfaceMuted, panel, accentSubtle, field].map(
          (background) => ({ background, minimum: 4.5 })
        )
      ),
      'content-muted': ensureContrastAcross(
        oklchToHex(0.47, Math.min(neutralChroma, 0.03), neutral.h),
        [surface, surfaceMuted, accentSubtle].map((background) => ({
          background,
          minimum: 4.5
        }))
      ),
      'content-faint': oklchToHex(
        0.71,
        Math.min(neutralChroma, 0.022),
        neutral.h
      ),
      accent,
      'accent-vivid': accentVivid,
      'accent-hover': oklchToHex(
        rgbToOklch(hexToRgb(accent)).L - 0.08,
        brand.C,
        brand.h
      ),
      'accent-subtle': accentSubtle,
      danger: ensureContrast(safeSeeds.danger, '#ffffff', 4.5),
      'danger-vivid': ensureContrast(safeSeeds.danger, surfaceMuted, 4.5),
      message: surface,
      'message-border': border,
      'message-own': messageOwn,
      'message-own-content': ensureContrast(
        oklchToHex(0.3, ownBubble.C * 1.6, ownBubble.h),
        messageOwn,
        4.5
      ),
      highlight: safeSeeds.highlight,
      'highlight-content': ensureContrast(
        bestForeground(safeSeeds.highlight),
        safeSeeds.highlight,
        4.5
      ),
      tooltip: oklchToHex(0.25, Math.min(neutralChroma, 0.02), neutral.h)
    }
  }

  const surface = oklchToHex(0.24, neutralChroma * 1.1, brand.h)
  const panel = oklchToHex(0.2, neutralChroma * 1.1, brand.h)
  const canvas = surface
  const surfaceMuted = oklchToHex(0.3, neutralChroma * 1.1, brand.h)
  // Same lightness as `surface-muted`, more chroma. Dark hover was reported
  // as the right DEPTH but too grey, and 1.1 put it at C 0.047 — below the
  // sent bubble's 0.074 and level with the plain surfaces, so it read as a
  // grey wash on a blue ground. 1.5 (C 0.064) sits inside the palette's blue
  // without reaching `field`'s 1.7, which would make a hovered row and an
  // input field the same colour.
  //
  // Note this branch takes its hue from `brand` while the light branch takes
  // it from `neutral` — that asymmetry is inherited from the surrounding
  // surface derivations, not introduced here.
  const surfaceHover = oklchToHex(0.3, neutralChroma * 1.5, brand.h)
  const messageOwn = oklchToHex(0.33, ownBubble.C * 1.9, ownBubble.h)
  const darkHighlight = oklchToHex(0.47, highlight.C, highlight.h)
  // Same story as `surface-hover` a few lines up, and the same fix. This was
  // `rgba(255, 255, 255, 0.07)` — a NEUTRAL wash. Composited on the canvas it
  // lands at L 0.302 (right, it reads at the correct depth) but C 0.043,
  // below every opaque plane around it (0.047) and far below the sent
  // bubble's 0.074. A received bubble therefore read as grey next to a blue
  // sent one, which is how it was reported.
  //
  // Derived opaquely now, at the lightness the wash was already producing so
  // the four `* on message` contrast floors do not move (they measure 11.32,
  // 5.25, 6.13 and 4.54 after this), with the chroma multiplier
  // `surface-hover` settled on. Being opaque also collapses
  // `messageBackground` — the composited value the contrast checks use —
  // into the token itself, so the two can no longer drift, and it matches the
  // light branch, where `message` is plain `surface`.
  //
  // This lands on effectively the same colour as `surface-hover` above (both
  // L 0.30, chroma * 1.5). That is tolerated rather than accidental: one
  // paints a hovered row in the list column, the other a bubble in the chat
  // column, and no layout puts them adjacent. If they ever do meet, this is
  // the one to move — the hover value was tuned against a specific
  // complaint, this one only needs to stay blue and keep its lightness.
  const message = oklchToHex(0.302, neutralChroma * 1.5, brand.h)
  const messageBackground = message
  const accentSubtle = toRgba(safeSeeds.brand, 0.17)
  const accentSubtleBackground = compositeHex(safeSeeds.brand, panel, 0.17)
  // Input-field fill. Note this goes UP in lightness where the light branch
  // goes down: in dark mode the field sits LIGHTER than the surface behind
  // it, so "deepen the field" — which in light means darker — would push it
  // toward the background here and make it less visible, not more. Both
  // branches are really doing the same thing, increasing separation from the
  // surrounding plane; the direction just inverts with the colour mode.
  // 0.32 lifts that separation from 1.326:1 to 1.424:1 while the placeholder
  // stays at 4.92:1.
  // Chroma multiplier 1.7, not the 0.9 this shipped with for a few hours.
  // Every dark plane sits around C 0.047-0.051 and the sent bubble at 0.074;
  // 0.9 put the field at 0.0386, the greyest thing on screen, so a
  // desaturated patch sat on a blue ground and read as dirty rather than as
  // a field. Dark planes take their HUE from `brand` but their CHROMA from
  // `neutral`, which is clamped at 0.045 — that pairing is what drifts
  // toward mud, and the multiplier is the only lever that pulls it back.
  // Contrast is indifferent to the CHROMA here: across 0.9 to 2.0 the
  // placeholder moves only 4.92 -> 4.90, so that part is a pure appearance
  // choice, not a trade.
  //
  // The LIGHTNESS is not free, and the cost is easy to miss. `field` is in
  // `darkTextBackgrounds` below, so `content-subtle` — the placeholder — is
  // corrected against it and the 4.5 floor holds at any L on its own. What
  // moves instead is `content-subtle` itself: lifting the field from 0.32 to
  // 0.38 brightens it from #90a4b6 to #9db2c4, i.e. 6.40 -> 7.51 against
  // `surface`. That token is the app-wide secondary-text colour, so the real
  // price of a lighter field is that ALL muted text gets brighter, not that
  // any floor breaks. Measure that, not the floor, before moving this again.
  const field = oklchToHex(0.3, neutralChroma * 1.7, brand.h)
  const darkTextBackgrounds = [
    surface,
    panel,
    canvas,
    surfaceMuted,
    messageBackground,
    accentSubtleBackground,
    field
  ]
  const accent = ensureContrastAcross(
    oklchToHex(0.56, brand.C * 0.55, brand.h),
    [
      { background: '#ffffff', minimum: 4.5 },
      { background: surface, minimum: 3 },
      { background: panel, minimum: 3 }
    ]
  )
  const accentVivid = ensureContrastAcross(
    oklchToHex(0.75, brand.C * 0.9, brand.h),
    [
      ...darkTextBackgrounds.map((background) => ({
        background,
        minimum: 4.52
      })),
      { background: messageOwn, minimum: 3 }
    ]
  )
  const border = oklchToHex(0.38, neutralChroma * 1.2, brand.h)
  // Hue comes from `brand`, like every other dark surface. It was a
  // hard-coded 56 — a warm yellow-grey — which made this the only token in a
  // 244-252 blue palette sitting at hue 52, and it showed wherever the token
  // is drawn as a visible outline (measured #a7a09c against a #02314f field).
  // Lightness and chroma are unchanged, so contrast is untouched at 5.24 ->
  // 5.25 against the field and the derivation's own 3:1 floors below still
  // govern the value; this only stops it reading as a different family.
  const borderStrong = ensureContrastAcross(oklchToHex(0.71, 0.02, brand.h), [
    ...[surface, panel, canvas, surfaceMuted, border].map((background) => ({
      background,
      minimum: 3
    }))
  ])

  return {
    surface,
    panel,
    canvas,
    'surface-muted': surfaceMuted,
    'surface-hover': surfaceHover,
    // 1.8 for the same reason as `field` above: at 1.2 the pill sat at
    // C 0.051 against a 0.074 sent bubble — neither clearly blue nor
    // clearly neutral, which is what reads as muddy. Text contrast is
    // unaffected by chroma (7.62 -> 7.58 across the whole range).
    //
    // Unlike `field`, this one is NOT self-correcting: its text is
    // `content-muted`, whose ensureContrastAcross list covers surface-muted
    // and accent-subtle but not surface-sunken. So the ceiling here is real
    // and fixed — at L 0.50 the pill text falls to 4.01 and breaks AA. 0.41
    // leaves it at 5.94. The floor is asserted in tokenContrast.test.ts
    // rather than enforced by the derivation, so a change here fails a test
    // instead of being silently absorbed.
    'surface-sunken': oklchToHex(0.365, neutralChroma * 1.8, brand.h),
    field,
    border,
    'border-strong': borderStrong,
    content: ensureContrast(
      oklchToHex(0.94, Math.min(text.C, 0.02), text.h),
      surface,
      4.5
    ),
    'content-subtle': ensureContrastAcross(
      oklchToHex(0.71, Math.min(neutralChroma, 0.035), brand.h),
      darkTextBackgrounds.map((background) => ({
        background,
        minimum: 4.52
      }))
    ),
    'content-muted': ensureContrastAcross(oklchToHex(0.87, 0.01, brand.h), [
      { background: surfaceMuted, minimum: 3 },
      { background: accentSubtleBackground, minimum: 4.5 }
    ]),
    'content-faint': ensureContrastAcross(
      oklchToHex(0.58, 0.027, brand.h),
      [panel, surface].map((background) => ({ background, minimum: 3 }))
    ),
    accent,
    'accent-vivid': accentVivid,
    'accent-hover': oklchToHex(
      rgbToOklch(hexToRgb(accent)).L - 0.08,
      brand.C * 0.55,
      brand.h
    ),
    'accent-subtle': accentSubtle,
    danger: ensureContrast(safeSeeds.danger, '#ffffff', 4.5),
    'danger-vivid': ensureContrastAcross(
      safeSeeds.danger,
      darkTextBackgrounds
        .filter((background) => background !== accentSubtleBackground)
        .map((background) => ({ background, minimum: 4.52 }))
    ),
    message,
    'message-border': 'transparent',
    'message-own': messageOwn,
    'message-own-content': ensureContrast(
      oklchToHex(0.92, ownBubble.C * 0.35, ownBubble.h),
      messageOwn,
      4.5
    ),
    highlight: darkHighlight,
    'highlight-content': ensureContrast(
      bestForeground(darkHighlight),
      darkHighlight,
      4.5
    ),
    tooltip: oklchToHex(0.29, neutralChroma * 1.2, brand.h)
  }
}

export function paletteSeeds(
  dark: boolean,
  source: DesignPalette = palette
): PaletteSeeds {
  return dark ? { ...source.light, ...source.dark } : { ...source.light }
}

/** Applies all derived tokens as inline CSS custom properties on an SDK root. */
export function applyPalette(
  root: HTMLElement,
  dark: boolean,
  source: DesignPalette = palette
): DesignTokens {
  const tokens = deriveTokens(paletteSeeds(dark, source), dark)
  for (const [name, value] of Object.entries(tokens)) {
    root.style.setProperty(`--color-${name}`, value)
  }
  return tokens
}
