/**
 * Publishes the usable viewport height as the `--imkit-viewport-height` custom
 * property on `<html>`, for every full-height SDK surface to size itself from.
 * Full-page iOS shells also bridge delayed keyboard-dismissal measurements
 * with an immediate restoration; keyboard-sized viewport changes take over.
 *
 * **`dvh` cannot do this job in an iOS webview.** Measured on iPhone 17 Pro /
 * iOS 26.5 (issue #20), focusing the composer in a WKWebView produces:
 *
 * | t (ms) | `innerHeight` | `100dvh` | `visualViewport.height` | `scrollY` |
 * | -----: | ------------: | -------: | ----------------------: | --------: |
 * |      0 |           729 |      729 |                     729 |         0 |
 * |    257 |           729 |      729 |                     408 |         0 |
 * |    291 |           408 |      729 |                     408 |       321 |
 *
 * The software keyboard shrinks the visual viewport, and ~35ms later WebKit
 * shrinks the layout viewport too — but `dvh` tracks NEITHER. It answers 729
 * throughout, because the keyboard is an "interactive widget" and the default
 * `interactive-widget=resizes-visual` leaves viewport units alone. So a root
 * sized `h-dvh` stays 729 tall inside a 408 tall layout viewport, the document
 * becomes scrollable, and WebKit scrolls it by the keyboard height to reveal
 * the focused composer — which is what pushes the chat header off screen.
 *
 * The declarative fix, `interactive-widget=resizes-content` in the viewport
 * meta, is unimplemented in WebKit (bug 259770, still NEW as of 2026-07), so
 * this has to be measured in JS.
 *
 * **The table above is a host that leaves its web view full height.** A host
 * that shrinks the web view for the keyboard instead — tribo's iOS app does
 * since this issue — moves the layout viewport itself, and `dvh` then follows
 * it about 12ms behind `innerHeight`. Measured that way the roots would be
 * nearly right with plain `h-dvh`, which makes this file look redundant if
 * tribo is the only place it is ever checked. It is not: mobile Safari, the
 * pinchat web component and any host that has not made that native change
 * still report the pre-keyboard height forever, and that is the case with the
 * lost header. Do not delete this on the strength of a tribo-only trace.
 *
 * Written on `document.documentElement` rather than on each SDK root so that
 * teleported layers — modals, dropdown menus, the shared portal host — inherit
 * it too. It is one namespaced custom property; nothing else on the host page
 * is touched. The static `100dvh` fallback lives in `src/style.css` and takes
 * over whenever no SDK surface is mounted.
 */

import { hostKeyboardTransition } from './hostKeyboardTransition'

const PROPERTY = '--imkit-viewport-height'

let subscribers = 0

const measure = (): number => {
  const layout = window.innerHeight
  const visual = window.visualViewport
  if (!visual) return layout
  // `visualViewport.height` is in visual-viewport pixels, so a pinch-zoom
  // shrinks it; multiplying by `scale` converts back to layout pixels, and the
  // app therefore does not shrink just because the user zoomed in. Taking the
  // smaller of the two means the keyboard is honoured from the FIRST event
  // that reports it, ~35ms before `innerHeight` catches up.
  return Math.min(layout, visual.height * visual.scale)
}

const publish = (height: number): void => {
  document.documentElement.style.setProperty(PROPERTY, `${height}px`)
}

// Phone traces show a 440-456ms delay between blur and the closing resize.
// Restore in one step on the next frame, without interpolating height. Keep a
// bounded fallback because blur alone does not prove that the keyboard closed.
const DISMISS_SETTLE_TIMEOUT = 600
// Shared threshold for distinguishing keyboard movement from toolbar jitter.
const MIN_KEYBOARD_HEIGHT = 100
let focusHeight: { height: number; width: number } | null = null
let dismissal: { from: number; to: number; width: number } | null = null
let dismissalFrame: number | null = null
let dismissalTimeout: number | null = null

const cancelDismissal = (): void => {
  if (dismissalFrame !== null) window.cancelAnimationFrame(dismissalFrame)
  if (dismissalTimeout !== null) window.clearTimeout(dismissalTimeout)
  dismissalFrame = null
  dismissalTimeout = null
  dismissal = null
}

const isTextInput = (element: Element | null): boolean =>
  element instanceof HTMLElement &&
  (element.isContentEditable ||
    element.matches(
      'textarea, input:not([type]), input[type="text"], input[type="search"], input[type="email"], input[type="password"], input[type="tel"], input[type="url"], input[type="number"], [contenteditable="true"], [contenteditable=""]'
    ))

const activeInput = (): Element | null => {
  let element = document.activeElement
  while (element?.shadowRoot?.activeElement) {
    element = element.shadowRoot.activeElement
  }
  return element
}

const canHandleIOSKeyboard = (): boolean =>
  subscribers > 0 &&
  !hostKeyboardTransition.supported.value &&
  window.visualViewport?.scale === 1 &&
  (/iPad|iPhone|iPod/.test(navigator.userAgent) ||
    (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1))

const write = (): void => {
  const height = measure()
  if (dismissal) {
    if (dismissal.width !== window.innerWidth || !canHandleIOSKeyboard()) {
      cancelDismissal()
      focusHeight = null
      publish(height)
      return
    }
    // Bridge only toolbar-sized changes near the open-keyboard height. A
    // keyboard-sized expansion takes over even below the old focus height:
    // Safari's toolbar may occupy more space after the keyboard closes.
    if (
      height >= dismissal.from &&
      height - dismissal.from < MIN_KEYBOARD_HEIGHT
    )
      return
    cancelDismissal()
    if (!isTextInput(activeInput())) focusHeight = null
  }
  publish(height)
}

const onFocusIn = (): void => {
  if (!isTextInput(activeInput()) || !canHandleIOSKeyboard()) return
  cancelDismissal()
  focusHeight ??= { height: measure(), width: window.innerWidth }
  write()
}

const onFocusOut = (event: FocusEvent): void => {
  const target = event.composedPath()[0]
  if (
    !(target instanceof Element) ||
    !isTextInput(target) ||
    !canHandleIOSKeyboard() ||
    !focusHeight ||
    focusHeight.width !== window.innerWidth
  ) {
    return
  }

  const from = measure()
  const to = focusHeight.height
  // A toolbar resize or rounding difference is not a software keyboard.
  if (to - from < MIN_KEYBOARD_HEIGHT) return
  cancelDismissal()
  dismissal = { from, to, width: window.innerWidth }
  const tick = (): void => {
    dismissalFrame = null
    // focusout precedes focusin when tabbing to another field. Check on the
    // next frame rather than expanding the shell between the two events.
    if (
      isTextInput(activeInput()) ||
      !canHandleIOSKeyboard() ||
      focusHeight?.width !== window.innerWidth
    ) {
      cancelDismissal()
      write()
      return
    }
    publish(to)
  }
  dismissalFrame = window.requestAnimationFrame(tick)
  // Blur is an early signal, not proof that the keyboard closed. Never leave
  // a predicted height behind if Safari doesn't send the expected resize.
  dismissalTimeout = window.setTimeout(() => {
    cancelDismissal()
    focusHeight = null
    write()
  }, DISMISS_SETTLE_TIMEOUT)
}

const resetKeyboardSession = (): void => {
  cancelDismissal()
  focusHeight = null
}

const onOrientationChange = (): void => {
  resetKeyboardSession()
  write()
}

const bind = (): void => {
  window.addEventListener('resize', write)
  window.addEventListener('orientationchange', onOrientationChange)
  window.visualViewport?.addEventListener('resize', write)
}

const unbind = (): void => {
  window.removeEventListener('resize', write)
  window.removeEventListener('orientationchange', onOrientationChange)
  window.visualViewport?.removeEventListener('resize', write)
  resetKeyboardSession()
  document.documentElement.style.removeProperty(PROPERTY)
}

/**
 * Starts tracking, and returns the matching stop function.
 *
 * Refcounted: several SDK surfaces can be mounted at once (`MainView` plus the
 * `ChatRoom` inside it, or two custom elements side by side) and each may call
 * this, but only one set of listeners is ever bound. The property is removed —
 * restoring the `100dvh` fallback — once the last caller has stopped.
 */
export function startViewportHeightTracking(): () => void {
  if (typeof window === 'undefined' || typeof document === 'undefined') {
    return () => {}
  }

  subscribers += 1
  if (subscribers === 1) bind()
  write()

  let stopped = false
  return () => {
    if (stopped) return
    stopped = true
    subscribers -= 1
    if (subscribers === 0) unbind()
  }
}

let scrollLockSubscribers = 0

const pinToTop = (): void => {
  if (window.scrollY === 0) return
  // Only the VERTICAL offset is ours to undo — that is the range the keyboard
  // opens and the one WebKit spends revealing the focused field. `scrollTo(0,
  // 0)` also zeroes x, which on a pinch-zoomed page yanks the reader back to
  // the left edge every time a pan happens to move y as well.
  window.scrollTo(window.scrollX, 0)
}

// Focus before Safari's pointer default can start its reveal animation.
// Correcting that animation with scrollTo keeps DOM coordinates at zero but
// makes the composited header jump down by the keyboard height on iOS 26.5.
// Leave the pointer default intact so it can place the caret or select text.
const onPointerDown = (event: PointerEvent): void => {
  if (event.button !== 0 || !canHandleIOSKeyboard()) return
  const input = event
    .composedPath()
    .find(
      (node): node is HTMLElement =>
        node instanceof HTMLElement &&
        isTextInput(node) &&
        (!node.isContentEditable || !node.parentElement?.isContentEditable)
    )
  if (
    !input ||
    input === activeInput() ||
    input.matches(':disabled, [readonly]')
  ) {
    return
  }
  input.focus({ preventScroll: true })
}

const bindScrollLock = (): void => {
  window.addEventListener('pointerdown', onPointerDown, true)
  window.addEventListener('scroll', pinToTop)
  window.visualViewport?.addEventListener('resize', pinToTop)
  window.visualViewport?.addEventListener('scroll', pinToTop)
  window.addEventListener('focusin', onFocusIn)
  window.addEventListener('focusout', onFocusOut)
}

const unbindScrollLock = (): void => {
  window.removeEventListener('pointerdown', onPointerDown, true)
  window.removeEventListener('scroll', pinToTop)
  window.visualViewport?.removeEventListener('resize', pinToTop)
  window.visualViewport?.removeEventListener('scroll', pinToTop)
  window.removeEventListener('focusin', onFocusIn)
  window.removeEventListener('focusout', onFocusOut)
  resetKeyboardSession()
  if (subscribers > 0) write()
}

/**
 * Holds the layout viewport at the top, and returns the matching stop
 * function.
 *
 * Sizing the SDK root to the measured height is necessary but not sufficient:
 * a software keyboard does not shrink the initial containing block, only the
 * unobscured height, so the page keeps a scrollable range of exactly the
 * keyboard height (729 - 408 = 321, the `scrollY` in the trace above) no
 * matter how short its content is. WebKit spends that range revealing the
 * focused composer, which drags the chat header off screen — the shorter root
 * just means blank space follows it down.
 *
 * Only a full-page SDK shell may call this. It makes the whole document
 * unscrollable, which is right for a shell that is exactly one viewport tall
 * and clips its own overflow, and wrong for an SDK component embedded in a
 * host page that scrolls. The `scrollY === 0` guard is what stops the
 * scroll listener from recursing.
 */
export function startViewportScrollLock(): () => void {
  if (typeof window === 'undefined') return () => {}

  scrollLockSubscribers += 1
  if (scrollLockSubscribers === 1) bindScrollLock()
  pinToTop()

  let stopped = false
  return () => {
    if (stopped) return
    stopped = true
    scrollLockSubscribers -= 1
    if (scrollLockSubscribers === 0) unbindScrollLock()
  }
}
