import { getConfig } from '../runtime/config'

// IM-Authorization / IM-Client-Key authenticate the host app to the imkit API
// (config.domain). Media bytes live on signed CDN URLs (S3/GCS) that authorize
// via the URL signature, so these credentials must never be sent cross-origin —
// doing so leaks them to the CDN and trips a CORS preflight those endpoints
// don't answer (see useMediaFetch). Returns true only when `url` is on the API
// origin, i.e. the one case where attaching the headers is correct. Any
// unparseable url or missing config.domain returns false (omit the headers).
export const isApiOrigin = (url: string): boolean => {
  try {
    return new URL(url).origin === new URL(getConfig().domain).origin
  } catch {
    return false
  }
}
