import { sha1Bytes } from './hash'
type IMVideo = {
  id: string
  width: number
  height: number
  thumbnailUrl: string
  originalUrl: string
  duration: number
  thumbnailId?: string
  thumbnailFile:
    | {
        id: string
        file: File
      }
    | null
    | undefined
}
export const file2video = (file: File): Promise<IMVideo> => {
  return new Promise((resolve, reject) => {
    const canvas = document.createElement('canvas')
    const context = canvas.getContext('2d')
    if (!context) {
      reject(new Error('Could not get canvas context'))
      return
    }
    const video = document.createElement('video')
    // Keep the object URL so it can be revoked: leaving it un-revoked orphans the
    // blob (and the whole video File it references) for the document lifetime.
    const objectUrl = URL.createObjectURL(file)
    video.src = objectUrl
    video.muted = true
    video.autoplay = true
    video.onloadedmetadata = () => {
      canvas.width = video.videoWidth
      canvas.height = video.videoHeight
    }
    video.onloadeddata = () => {
      context.drawImage(video, 0, 0, canvas.width, canvas.height)
      // The frame is captured; the video element is no longer needed (duration is
      // already loaded), so release the object URL now — this covers the success
      // path and all three reject paths that flow through here.
      URL.revokeObjectURL(objectUrl)
      canvas.toBlob(async (blob) => {
        if (!blob) {
          reject(new Error('Could not create blob'))
          return
        }
        const imageFile = new File([blob], 'snapshot.jpg', {
          type: 'image/jpeg'
        })
        const reader = new FileReader()
        reader.onloadend = async () => {
          try {
            resolve({
              // Hash the actual file/blob bytes (content-derived, deterministic
              // and reproducible from the source) — NOT video.src, which is a
              // random blob: URL that yields a different id for identical content.
              id: await sha1Bytes(new Uint8Array(await file.arrayBuffer())),
              width: canvas.width,
              height: canvas.height,
              duration: video.duration,
              thumbnailUrl: reader.result as string,
              originalUrl: '',
              thumbnailFile: {
                // Hash the JPEG blob actually uploaded — canvas.toDataURL()
                // defaults to PNG, so it would hash different bytes than the file.
                id: await sha1Bytes(new Uint8Array(await blob.arrayBuffer())),
                file: imageFile
              }
            })
          } catch (error) {
            reject(error)
          }
        }
        reader.onerror = () => {
          reject(reader.error)
        }
        reader.readAsDataURL(blob)
      }, 'image/jpeg')
    }
    video.onerror = () => {
      URL.revokeObjectURL(objectUrl)
      reject(new Error('Could not load video'))
    }
  })
}
export default IMVideo
