<script setup lang="ts">
import {
  ChevronDown,
  ChevronRight,
  Folder as FolderIcon,
  FolderOpen
} from 'lucide-vue-next'
import { computed } from 'vue'
import { SearchType } from '../enums/searchType'
import { useImkitStore } from '../stores/imkit'
import Folder from './../classes/folder'
import Room from './../classes/room'
import HighlightedText from './HighlightedText.vue'

const props = defineProps<{ source: Folder }>()
const imkit = useImkitStore()

const searchKeyword = computed(() => {
  if (
    imkit.searchKeyword.length > 0 &&
    imkit.searchType === SearchType.RoomPrefFolder
  ) {
    return imkit.searchKeyword
  }
  return undefined
})
const selectedFolderId = computed(() => {
  return imkit.selectedFolderId
})
const numberOfUread = computed(() => {
  return props.source.roomIds.reduce((acc, roomId) => {
    const room: Room = imkit.rooms[roomId]
    if (room) {
      return acc + room.numberOfUnread
    }
    return acc
  }, 0)
})
const roomTag = computed(() => {
  return imkit.roomTag
})
const numberOfChatroom = computed(() => {
  return props.source.roomIds
    .map((id: string) => imkit.rooms[id])
    .filter((room: Room) => {
      if (roomTag.value) {
        return room && room.roomTags.includes(roomTag.value)
      }
      return room
    }).length
})
const actionMenuRoomId = computed(() => imkit.actionMenuRoomId)
const toggle = () => {
  // Only the ROOM action menu can suppress selection now. The folder menu
  // that set actionMenuFolderId was removed with f7632d6 — management moved
  // into the manage-folders dialog — so that half of the guard could only
  // ever read '' and was dead.
  if (actionMenuRoomId.value) {
    return
  }
  if (imkit.selectedFolderId === props.source.id) {
    imkit.$patch({ selectedFolderId: '' })
  } else {
    imkit.$patch({ selectedFolderId: props.source.id })
  }
}
// Rename/delete moved to the 「管理資料夾」 dialog (ManageFoldersModal.vue),
// opened from the 「管理」 entry beside the 資料夾 heading — this row no
// longer owns its own edit/delete affordance.
</script>

<template>
  <!--
    Full-bleed row on RoomCell.vue's own grid: no `mx-2`/`mt-2`/`rounded-lg`
    card, no separate default fill. `min-h-[68px] px-4 py-2.5 gap-3` and the
    50px leading box are copied verbatim from RoomCell.vue so a folder row
    and a room row share the same left/right column edges — that sharing is
    the entire point of this change, not an incidental resemblance. A folder
    is told apart from a conversation by the glyph's shape (rounded square
    vs. circle), never by indentation or a card.
  -->
  <div
    :data-testid="`folder-tab-${source.id}`"
    class="group relative flex min-h-[68px] cursor-pointer items-center gap-3 px-4 py-2.5 select-none sm:hover:bg-surface-hover"
    @click="toggle"
  >
    <div
      data-testid="folder-icon-shell"
      class="relative flex h-[50px]! w-[50px]! shrink-0 items-center justify-center rounded-lg bg-accent-subtle text-accent-vivid transition-colors sm:group-hover:bg-surface"
    >
      <FolderOpen v-if="selectedFolderId === source.id" :size="24" />
      <FolderIcon v-else :size="24" />
    </div>
    <div class="flex w-0 min-w-0 grow flex-col text-left">
      <div
        class="overflow-hidden text-base text-ellipsis whitespace-nowrap text-content"
      >
        <highlighted-text :text="source.name" :highlight="searchKeyword" />
      </div>
      <div
        class="overflow-hidden text-base text-ellipsis whitespace-nowrap text-content-subtle"
      >
        {{
          numberOfChatroom
            ? $t('numberOfChatroom', numberOfChatroom)
            : $t('no-chatroom')
        }}
      </div>
    </div>
    <!--
      Right-hand column: unread count, then the expand/collapse chevron —
      same `px-4` right edge as RoomCell's own right-hand number, so the two
      share a right edge even though the room row's count sits on its
      second line rather than its first.
    -->
    <div class="ml-auto flex shrink-0 items-center gap-1.5">
      <div
        v-if="numberOfUread > 0"
        class="flex h-5 min-w-5 items-center justify-center rounded-full bg-danger px-1.5 text-center text-xs leading-none font-semibold text-white"
      >
        {{ numberOfUread }}
      </div>
      <ChevronDown
        v-if="selectedFolderId === source.id"
        class="h-4 w-4 text-content-muted"
      />
      <ChevronRight v-else class="h-4 w-4 text-content-muted" />
    </div>
  </div>
</template>

<style scoped></style>
