const DropdownMenuCheckboxItem = defineComponent({
  name: 'DropdownMenuCheckboxItem',
  inheritAttrs: false,
  props: {
    class: {
      type: null,
      default: undefined
    },
    hideIndicator: {
      type: Boolean,
      default: false
    }
  },
  setup(props, { slots, attrs }) {
    return () => {
      const itemAttrs = { ...attrs } as Record<string, unknown>
      const className = itemAttrs.class as ClassValue
      delete itemAttrs.class

      return h(
        DropdownMenuCheckboxItemPrimitive,
        {
          ...itemAttrs,
          class: cn(
            'hover:bg-surface-hover focus:bg-surface-hover focus-visible:ring-1 focus-visible:ring-accent focus-visible:ring-inset relative flex cursor-pointer items-center rounded-sm text-sm transition-colors outline-none select-none data-[disabled]:pointer-events-none data-[disabled]:opacity-50',
            props.hideIndicator ? 'px-2 py-1.5' : 'py-1.5 pr-2 pl-8',
            className,
            props.class as ClassValue
          )
        },
        {
          default: () => [
            props.hideIndicator
              ? null
              : h(
                  'span',
                  {
                    class:
                      'absolute left-2 flex h-3.5 w-3.5 items-center justify-center'
                  },
                  h(DropdownMenuItemIndicator, null, () =>
                    h(Check, { class: 'h-4 w-4' })
                  )
                ),
            slots.default?.()
          ]
        }
      )
    }
  }
})

const DropdownMenuRadioItem = defineComponent({
  name: 'DropdownMenuRadioItem',
  inheritAttrs: false,
  props: {
    class: {
      type: null,
      default: undefined
    },
    indicatorPosition: {
      type: String,
      default: 'start'
    }
  },
  setup(props, { slots, attrs }) {
    return () => {
      const itemAttrs = { ...attrs } as Record<string, unknown>
      const className = itemAttrs.class as ClassValue
      delete itemAttrs.class

      return h(
        DropdownMenuRadioItemPrimitive,
        {
          ...(itemAttrs as any),
          class: cn(
            'hover:bg-surface-hover focus:bg-surface-hover focus-visible:ring-1 focus-visible:ring-accent focus-visible:ring-inset relative flex cursor-pointer items-center rounded-sm py-1.5 text-sm transition-colors outline-none select-none data-[disabled]:pointer-events-none data-[disabled]:opacity-50',
            props.indicatorPosition === 'end' ? 'pr-8 pl-2' : 'pr-2 pl-8',
            className,
            props.class as ClassValue
          )
        },
        {
          default: () => [
            h(
              'span',
              {
                class: cn(
                  'absolute flex h-3.5 w-3.5 items-center justify-center',
                  props.indicatorPosition === 'end' ? 'right-2' : 'left-2'
                )
              },
              h(
                DropdownMenuItemIndicator,
                null,
                () =>
                  slots.indicator?.() ??
                  h(Circle, { class: 'h-2 w-2 fill-current' })
              )
            ),
            slots.default?.()
          ]
        }
      )
    }
  }
})

