export class Lock {
    #lockP = null;
    async lock() {
        const previous = this.#lockP;
        const { promise, resolve } = Promise.withResolvers();
        this.#lockP = promise;
        await previous;
        return resolve;
    }
    withLock(f) {
        return run(this.lock(), f);
    }
}
export class RWLock {
    #lock = new Lock();
    #writeP = null;
    #readP = [];
    read() {
        return this.#lock.withLock(async () => {
            await this.#writeP;
            const { promise, resolve } = Promise.withResolvers();
            this.#readP.push(promise);
            return resolve;
        });
    }
    withRead(f) {
        return run(this.read(), f);
    }
    async write() {
        return await this.#lock.withLock(async () => {
            await this.#writeP;
            await Promise.all(this.#readP);
            const { promise, resolve } = Promise.withResolvers();
            this.#writeP = promise;
            this.#readP = [];
            return resolve;
        });
    }
    withWrite(f) {
        return run(this.write(), f);
    }
}
async function run(p, f) {
    const release = await p;
    try {
        return await f();
    }
    finally {
        release();
    }
}
